let UNITS = { U: '小便器', C: '大便器', D: '多目的', L: '洗面器', M: '手洗い器', H: '歯磨き器', SK: '掃除用流し' };
const unitLabel = u => (u && UNITS[u]) ? `${u}ユニット（${UNITS[u]}）` : '';
// そのユニットで使う入力項目（対象ユニットが空欄の項目は全部のユニットで使う）
const defsFor = u => paramDefs.filter(x => !x.units || !x.units.length || (u && x.units.includes(u)));
// パラメータ2の値からユニットのコードを取り出す
function unitFromValue(v) {
  const c = String(v || '').split(/[:：]/)[0].trim().toUpperCase();
  if (UNITS[c]) return c;
  return Object.keys(UNITS).find(k => String(v || '').includes(UNITS[k])) || '';
}
