if (window.pdfjsLib) pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
const REFRESH_SEC = 30;    // 一覧の自動更新間隔（秒）

const INFO_KEYS = ['指図NO','出荷指示NO','組立品番','品名','工事NO','工事名','組立場所','出荷日','組立日','製作台数','組立台数','パラメータ文字列','適用階','組図番号','備考'];

/* ===================== 起動 ===================== */
kumitateOnReady( async () => {
  $('#btnSearch').onclick = () => search($('#code').value);
  $('#code').addEventListener('keydown', e => { if (e.key === 'Enter') search($('#code').value); }); // USB/Bluetoothスキャナ対応
  $('#photo').onchange = scanPhoto;
  $('#photoPick').onchange = scanPhoto;
  $('#staff').value = store('staff');            // 前回入力した名前を表示
  $('#staff').onchange = () => {
    $('#staff').value = normName($('#staff').value);
    store('staff', $('#staff').value);
    if (view === 'list') renderList(); else if (cur) renderStatus();
  };
  $('#main').addEventListener('click', onMainClick);
  $('#stepper').addEventListener('click', onStepperClick);
  $('#listView').addEventListener('click', onListClick);
  $('#btnList').onclick = () => showView('list');
  $('#btnOffice').onclick = openOffice;
  $('#offFiles').onchange = analyzeOfficeFiles;
  $('#offParamBtn').onclick = importPasted;
  $('#offParamFile').onchange = readParamCsv;
  $('#offParamPdf').onchange = readParamPdfFile;
  $('#prClose').onclick = closeParamReview;
  $('#prView').addEventListener('click', onParamReviewEvent);
  $('#prView').addEventListener('input', onParamReviewEvent);
  $('#stdFiles').onchange = pickStdFiles;
  $('#offReload').onclick = e => { e.preventDefault(); loadOfficeStatus(); };
  $('#autoReload').onclick = e => { e.preventDefault(); loadAutoStatus(); };
  $('#officeView').addEventListener('change', e => {
    const k = e.target.dataset && e.target.dataset.pgtype;
    if (k !== undefined) { office.pages[Number(k)].type = e.target.value; renderOffice(); }
    const ck = e.target.dataset && e.target.dataset.csvkind;
    if (ck !== undefined) { office.csv[Number(ck)].kind = e.target.value; renderOffice(); }
    const o = e.target.dataset && e.target.dataset.pgowner;
    if (o !== undefined) { office.pages[Number(o)].forceId = e.target.value; renderOffice(); }
  });
  $('#officeView').addEventListener('click', e => {
    if (e.target.closest('[data-offreg]')) return registerOffice();
    if (e.target.closest('[data-autorun]')) return runAutoNow();
    if (e.target.closest('[data-autoon]')) return enableAuto();
    const pr = e.target.closest('[data-offpread]');
    if (pr) return readOfficeParamPage(pr.dataset.offpread);
    if (e.target.closest('[data-stdsave]')) return saveStdFiles();
    if (e.target.closest('[data-stdcollect]')) return collectStd();
    const cb = e.target.closest('[data-offsel]');
    if (cb) { e.stopPropagation(); cb.checked ? offSel.add(cb.dataset.offsel) : offSel.delete(cb.dataset.offsel); return renderOfficeStatus(); }
    if (e.target.closest('td.sel')) { const c = e.target.closest('tr').querySelector('[data-offsel]'); if (c) c.click(); return; }
    const all = e.target.closest('[data-offselall]');
    if (all) { document.querySelectorAll('[data-offsel]').forEach(c => all.checked ? offSel.add(c.dataset.offsel) : offSel.delete(c.dataset.offsel)); return renderOfficeStatus(); }
    if (e.target.closest('[data-offselclear]')) { offSel.clear(); return renderOfficeStatus(); }
    if (e.target.closest('[data-offdel]')) return deleteSelectedOrders([...offSel]);
    const f = e.target.closest('[data-offfilter]');
    if (f) { offFilter = f.dataset.offfilter; return renderOfficeStatus(); }
    const tr = e.target.closest('[data-offopen]');
    if (tr) search(tr.dataset.offopen);
  });
  $('#officeView').addEventListener('input', e => {
    if (e.target.id !== 'offQ') return;
    offQ = e.target.value;
    const pos = e.target.selectionStart;
    renderOfficeStatus();
    const q = $('#offQ'); q.focus(); q.setSelectionRange(pos, pos);   // 入力中の文字を消さない
  });
  $('#pbClose').onclick = () => { $('#printBox').hidden = true; };
  $('#tokuzuFile').onchange = uploadTokuzu;
  $('#pvClose').onclick = closePartsView;
  // 画面内のリンク（目次など）。GASの画面では「#…」のリンクがページ全体の移動になって真っ白になるので、
  // 移動はさせずに、その欄までスクロールする（閉じている欄は開く）
  document.addEventListener('click', e => {
    const a = e.target.closest('a[href^="#"]');
    if (!a) return;
    e.preventDefault();
    e.stopPropagation();
    const id = decodeURIComponent(a.getAttribute('href').slice(1));
    if (id === 'parts') return openPartsView();
    const el = document.getElementById(id);
    if (!el) return;
    const det = el.matches('details') ? el : el.querySelector(':scope > details') || el.closest('details');
    if (det && !det.open) det.open = true;
    if (view === 'detail') return showPlace(el);
    el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, true);
  document.addEventListener('click', e => { const t = e.target.closest('[data-wtab]'); if (t) setTab(t.dataset.wtab); });
  $('#pvSearch').addEventListener('input', () => renderPartsTable());
  $('#pvTabs').addEventListener('click', e => { const t = e.target.closest('[data-pvtab]'); if (t) showPartsTab(t.dataset.pvtab); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && !$('#partsView').hidden) closePartsView(); });
  $('#pbPrint').onclick = () => {
    document.body.classList.add('printing');
    setTimeout(() => { window.print(); document.body.classList.remove('printing'); }, 100);
  };
  $('#code').addEventListener('input', () => { if (view === 'list') renderList(); });

  try {
    const d = await run('getInitData');
    staffList = d.staff; managerList = d.managers; paramDefs = d.paramDefs || []; UNITS = d.units || UNITS;
    $('#staffNames').innerHTML = staffList.map(n => `<option value="${esc(n)}">`).join('');
    $('#managerNames').innerHTML = managerList.map(n => `<option value="${esc(n)}">`).join('');
  } catch (e) {
    alert('初期読み込みに失敗しました：' + e.message);
  }
  showView('list');

  // 一覧を自動更新（他の人の作業開始・完了が反映される）
  setInterval(() => { if (view === 'list' && !document.hidden) refreshList(true); }, REFRESH_SEC * 1000);
  document.addEventListener('visibilitychange', () => { if (!document.hidden && view === 'list') refreshList(true); });
});

/* ===================== 画面切り替え ===================== */
function showView(v) {
  view = v;
  $('#listView').hidden = v !== 'list';
  $('#main').hidden = v !== 'detail';
  $('#officeView').hidden = v !== 'office';
  $('#nav').hidden = true;
  document.body.classList.toggle('in-detail', v === 'detail');
  $('#offNav').hidden = v !== 'office';
  if (v !== 'detail') { stepVisible = false; updateStepper(); }
  else { stepVisible = wtab === 'drawing'; updateStepper(); views.forEach((_, i) => { if ($('#st-' + i)) applyZoom(i); }); }
  if (v === 'list') refreshList();
  window.scrollTo({ top: 0 });
}

/* ===================== 指示書一覧 ===================== */
async function refreshList(silent) {
  try {
    const r = await run('listOrders');
    orders = r.orders;
    $('#listUpdated').textContent = '最終更新 ' + r.now + '（' + REFRESH_SEC + '秒ごとに自動更新）';
    renderList();
  } catch (e) {
    if (!silent) alert('一覧の読み込みに失敗しました：' + e.message);
  }
}

function renderList() {
  const me = getMe();
  const q = $('#code').value.trim().toUpperCase();
  const match = o => !q || [o.id, o.shipNo, o.hinban, o.name, o.koji, o.floor]
    .some(v => String(v || '').toUpperCase().includes(q));
  const byDate = (a, b) => (a.shipDate || a.asmDate || '9999').localeCompare(b.shipDate || b.asmDate || '9999');

  const todo  = orders.filter(o => o.state === '未着手').sort(byDate);
  const doing = orders.filter(o => o.state === '作業中').sort((a, b) => a.startAt.localeCompare(b.startAt));
  const done  = orders.filter(o => o.state === '完了').sort((a, b) => b.doneAt.localeCompare(a.doneAt));
  $('#cTodo').textContent = todo.length;
  $('#cDoing').textContent = doing.length;
  $('#cDone').textContent = done.length;

  // 自分が作業中の指示書は、どのタブでも一番上に表示
  const mine = doing.filter(o => me && o.worker === me);
  $('#myWork').innerHTML = mine.length
    ? `<div class="sec-title">あなたが作業中</div><div class="olist">${mine.map(card).join('')}</div>` : '';

  let list = tab === 'todo' ? todo : tab === 'doing' ? doing.filter(o => !mine.includes(o)) : done;
  list = list.filter(match);
  const emptyMsg = { todo: '未着手の指示書はありません', doing: '他に作業中の指示書はありません', done: '直近の完了はありません' }[tab];
  $('#orderList').innerHTML = list.length ? list.map(card).join('') : `<div class="empty">${q ? '該当する指示書がありません' : emptyMsg}</div>`;
}

function card(o) {
  const me = getMe();
  const mine = o.state === '作業中' && me && o.worker === me;
  const cls = o.state === '完了' ? 'done' : o.state === '作業中' ? (mine ? 'doing mine' : 'doing') : '';
  const hm = s => String(s || '').slice(11, 16);   // 'yyyy/MM/dd HH:mm:ss' → 'HH:mm'
  let act;
  if (o.state === '未着手') {
    act = `<span class="tag">未着手</span><button class="btn primary" data-start="${esc(o.id)}">作業開始</button>`;
  } else if (mine) {
    act = `<span class="tag mine">作業中（あなた）${esc(hm(o.startAt))}〜</span><button class="btn primary" data-open="${esc(o.id)}">続ける</button>`;
  } else if (o.state === '作業中') {
    act = `<span class="tag doing">${esc(o.worker)} 作業中 ${esc(hm(o.startAt))}〜</span><button class="btn" data-open="${esc(o.id)}">見る</button>`;
  } else {
    act = `<span class="tag done">完了 ${esc(o.worker)} ${esc(String(o.doneAt).slice(5, 16))}</span><button class="btn" data-open="${esc(o.id)}">見る</button>`;
  }
  return `<div class="ocard ${cls}">
    <div class="o-main" data-open="${esc(o.id)}">
      <div class="o-hin mono">${esc(o.hinban || o.id)}${o.unit ? `<span class="unit" title="${esc(unitLabel(o.unit))}">${esc(o.unit)}<small>${esc(UNITS[o.unit] || '')}</small></span>` : ''}</div>
      <div class="o-sub">${esc([o.koji, o.floor, o.name].filter(Boolean).join(' / '))}</div>
      <div class="o-meta">${o.state !== '完了' ? dueChip(o.shipDate) : ''}${[o.shipDate && '出荷 ' + esc(o.shipDate), o.asmDate && '組立 ' + esc(o.asmDate), o.qty && esc(o.qty) + '台'].filter(Boolean).join('　')}</div>
      ${o.total ? `<div class="o-meta">部品 ${o.total}点</div>` : ''}
    </div>
    <div class="o-act">${act}</div>
  </div>`;
}

// 出荷日が近い指示書に札をつける（今日・明日・過ぎている）
function dueChip(s) {
  const m = String(s || '').match(/(\d{4})\D(\d{1,2})\D(\d{1,2})/);
  if (!m) return '';
  const t = new Date(); t.setHours(0, 0, 0, 0);
  const diff = Math.round((new Date(+m[1], m[2] - 1, +m[3]) - t) / 864e5);
  if (diff < 0) return '<span class="due over">出荷日を過ぎています</span>';
  if (diff === 0) return '<span class="due today">本日出荷</span>';
  if (diff === 1) return '<span class="due tmrw">明日出荷</span>';
  return '';
}

async function onListClick(e) {
  const t = e.target.closest('[data-tab]');
  if (t) {
    tab = t.dataset.tab;
    document.querySelectorAll('[data-tab]').forEach(b => b.classList.toggle('on', b === t));
    return renderList();
  }
  const s = e.target.closest('[data-start]');
  if (s) {
    const id = s.dataset.start;
    if (await doStart(id)) search(id); else refreshList();
    return;
  }
  const o = e.target.closest('[data-open]');
  if (o) return search(o.dataset.open);
}

/* ===================== 作業開始・取り消し ===================== */
// 成功したらサーバーの結果（開始日時など）を返す。失敗・中止なら null
async function doStart(id) {
  const staff = needStaff();
  if (!staff) return null;
  loading(true);
  try {
    let r = await run('startWork', id, staff, false);
    if (!r.ok && r.reason === 'own') {
      loading(false);
      if (!confirm(`あなたは他の指示書（${r.other.join('、')}）も作業中です。\nこちらも開始しますか？`)) return null;
      loading(true);
      r = await run('startWork', id, staff, true);
    }
    if (!r.ok) {
      alert(r.reason === 'taken'
        ? `${r.by}さんが先に作業を開始しました（${r.at}）。\n別の指示書を選んでください。`
        : 'この指示書は完了済みです。');
      return null;
    }
    toast('作業を開始しました');
    return r;
  } catch (e) {
    alert('作業開始に失敗しました：' + e.message);
    return null;
  } finally {
    loading(false);
  }
}

async function doCancel() {
  const s = cur.status, me = getMe(), id = cur.order['指図NO'];
  const msg = s.state === '完了' ? 'この指示書を「未着手」に戻しますか？'
    : (s.worker && s.worker !== me ? `${s.worker}さんの作業開始を取り消しますか？` : '作業開始を取り消しますか？');
  if (!confirm(msg + '\n（チェック済みの部品や保存済みの記録は残ります）')) return;
  loading(true);
  try {
    await run('cancelWork', id);
    toast('取り消しました');
  } catch (e) {
    alert('取り消しに失敗しました：' + e.message);
  } finally {
    loading(false);
  }
  search(id);
}

function renderStatus() {
  const s = cur.status, me = getMe();
  const o = cur.order;
  let html = `<button class="btn back" data-act="back" aria-label="一覧に戻る"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg>一覧</button>
    <div class="ident"><b class="mono">${esc(o['組立品番'] || o['指図NO'])}</b>${cur.unit ? `<span class="unit">${esc(cur.unit)}<small>${esc(UNITS[cur.unit] || '')}</small></span>` : ''}
      <small>${esc([o['工事名'], o['適用階'], o['組立台数'] && o['組立台数'] + '台', o['出荷日'] && '出荷 ' + o['出荷日']].filter(Boolean).join('　'))}</small></div>
    <label class="btn qr" for="photo" title="別の指示書のQRを撮影">QR</label><div class="grow">`;
  if (s.state === '未着手') {
    html += `<span class="tag">未着手</span></div><button class="btn primary" data-act="start">作業開始</button>`;
  } else if (s.state === '作業中') {
    html += `<span class="tag ${s.worker === me ? 'mine' : 'doing'}">${esc(s.worker)} 作業中 ${esc(String(s.startAt).slice(11, 16))}〜</span></div>
      <button class="btn danger" data-act="cancel">開始を取り消す</button>`;
  } else {
    html += `<span class="tag done">完了 ${esc(s.worker)} ${esc(String(s.doneAt).slice(5, 16))}</span></div>
      <button class="btn danger" data-act="cancel">未着手に戻す</button>`;
  }
  if (officePin) html += `<button class="btn danger" data-act="delOrder">この指示書を削除</button>`;
  $('#statusBar').innerHTML = html;
}

/* ===================== 担当者名（入力式） ===================== */
// 名前の空白を取り除いて統一（「堀江 」と「堀江」を同じ人として扱う）
function normName(s) { return String(s || '').replace(/[\s　]+/g, ''); }
function getMe() { return normName($('#staff').value); }

function needStaff() {
  const v = getMe();
  $('#staff').value = v;
  if (!v) { alert('右上に自分の名前を入力してください'); $('#staff').focus(); }
  return v;
}
// 名前の入力欄（候補つき）
function nameInput(id, value, listId) {
  return `<input id="${id}" list="${listId || 'staffNames'}" value="${esc(value || '')}" placeholder="名前を入力" autocomplete="off">`;
}
function nameVal(id) { return normName($('#' + id).value); }

/* ===================== QR読取（写真を撮って読む） =====================
 * GASのWebアプリはGoogleの画面の「枠の中」で動くため、スマホではリアルタイムのカメラが使えません。
 * そのため、スマホ標準のカメラで撮った写真からコードを読み取ります。
 * 読む順番：① ZXing（QR以外のDataMatrix等も対応）→ ② 端末内蔵の読取機能 → ③ jsQR
 */
async function scanPhoto(e) {
  const file = e.target.files[0];
  e.target.value = '';
  if (!file) return;
  loading(true);
  let info = '';
  try {
    const r = await decodeImage(file);
    info = r.info;
    if (!r.text) throw new Error('not found');
    if (navigator.vibrate) navigator.vibrate(100);
    $('#code').value = r.text;
    search(r.text);
  } catch (err) {
    loading(false);
    alert('コードを読み取れませんでした。\n・コードに近づき、画面の半分くらいの大きさで撮る\n・ピントを合わせ、影や光の反射を避ける\nを試してください。\n\n［診断］' + (info || err.message));
  }
}

function loadImage(file) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => { URL.revokeObjectURL(url); resolve(img); };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('画像を開けません')); };
    img.src = url;
  });
}

// 写真の一部（box＝[左, 上, 幅, 高さ] を0〜1の割合で指定）を、指定の大きさ以下にして画素データにする
// 向きの補正はブラウザが行う
function toImageData(img, maxSide, box) {
  const w0 = img.naturalWidth || img.width, h0 = img.naturalHeight || img.height;
  const b = box || [0, 0, 1, 1];
  const sx = Math.round(w0 * b[0]), sy = Math.round(h0 * b[1]);
  const cw = Math.round(w0 * b[2]), ch = Math.round(h0 * b[3]);
  const scale = Math.min(1, maxSide / Math.max(cw, ch));
  const w = Math.round(cw * scale), h = Math.round(ch * scale);
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(img, sx, sy, cw, ch, 0, 0, w, h);
  return ctx.getImageData(0, 0, w, h);
}

async function decodeImage(file) {
  return decodeSource(await loadImage(file));
}

// 画像またはキャンバスからコードを読む
async function decodeSource(img) {
  const log = [`画像${img.naturalWidth || img.width}×${img.naturalHeight || img.height}`];
  // 試す順番 [最大サイズ, 切り出し範囲]
  // 指示書のQRは小さく情報量が多いので、縮めすぎると読めない。
  // シート全体を撮った写真でも読めるよう、原寸に近い大きさ → 4隅の切り出し → 縮小 の順に試す
  const FULL = [0, 0, 1, 1];
  const tries = [
    [2400, FULL], [4000, FULL],
    [2400, [0, 0, 0.55, 0.55]], [2400, [0.45, 0, 0.55, 0.55]],
    [2400, [0, 0.45, 0.55, 0.55]], [2400, [0.45, 0.45, 0.55, 0.55]],
    [2400, [0.2, 0.2, 0.6, 0.6]], [1200, FULL],
  ];

  // ① ZXing（一番強力）
  if (window.ZXingWASM) {
    try {
      for (const [max, box] of tries) {
        const r = await ZXingWASM.readBarcodes(toImageData(img, max, box),
          { tryHarder: true, tryInvert: true, formats: [], maxNumberOfSymbols: 4 });
        // 2次元コードを優先（下のバーコードより指示書左上のコードを使う）
        const ok = r.filter(x => x.isValid && x.text);
        const hit = ok.find(x => !/Code|EAN|UPC|ITF|Codabar|DataBar/i.test(x.format)) || ok[0];
        if (hit) return { text: hit.text, format: hit.format };
      }
      log.push('ZXing:未検出');
    } catch (e) { log.push('ZXing:エラー ' + e.message); }
  } else {
    log.push('ZXing:読込失敗');
  }

  // ② 端末内蔵の読取機能（Android Chrome等）
  if ('BarcodeDetector' in window) {
    try {
      const formats = await BarcodeDetector.getSupportedFormats();
      const r = await new BarcodeDetector({ formats }).detect(img);
      if (r.length) return { text: r[0].rawValue, format: r[0].format };
      log.push('内蔵:未検出');
    } catch (e) { log.push('内蔵:エラー'); }
  }

  // ③ jsQR（普通のQRのみ）
  if (window.jsQR) {
    for (const [max, box] of tries) {
      const d = toImageData(img, max, box);
      const r = jsQR(d.data, d.width, d.height, { inversionAttempts: 'attemptBoth' });
      if (r && r.data) return { text: r.data, format: 'QRCode' };
    }
    log.push('jsQR:未検出');
  }
  return { text: '', info: log.join(' / ') };
}

/* ===================== 検索・表示 ===================== */
async function search(code) {
  code = String(code || '').trim();
  if (!code) return;
  loading(true);
  try {
    const d = await run('lookupOrder', code);
    if (!d.found) { renderNotFound(d.code); return showView('detail'); }
    render(d);
    if (d.autoRegistered) toast('QRの内容から指示書を登録しました');
    $('#code').value = '';
    showView('detail');
  } catch (e) {
    alert('指示書を開けませんでした。\n' + (e && e.message ? e.message : e) +
      '\n\n（何度も出る場合は、この画面のスクリーンショットを送ってください）');
    if (window.console) console.error(e);
  } finally {
    loading(false);
  }
}

async function autoExpandDrawings() {
  if (!cur || !cur.order || !cur.order['指図NO']) return;
  if (inkMode || setTarget) return alert('書き込みや位置設定を完了してから押してください。');
  if ($('#pformBox') && $('#pformBox').innerHTML.trim()) return alert('パラメータの入力を保存または閉じてから押してください。');
  const changed=Array.from(document.querySelectorAll('[data-manual-value],[data-dim-value]')).some(el=>{
    const key=el.dataset.manualValue||el.dataset.dimValue, parts=key.split(':').map(Number);
    const p=cur.drawings[parts[0]] && cur.drawings[parts[0]].points[parts[1]];
    return p && String(el.value||'').trim()!==String(p.write||'').trim();
  });
  if(changed) return alert('入力中の寸法を保存してから押してください。');
  const orderNo=cur.order['指図NO']; loading(true);
  try {
    const d=await run('lookupOrder',orderNo);
    if(!d.found) throw new Error('指示書が見つかりません');
    if(!cur || String(cur.order['指図NO'])!==String(orderNo)) return;
    d.params=d.params||[];d.calc=d.calc||[];d.drawings=(d.drawings||[]).map(x=>Object.assign({points:[]},x));
    ['params','calc','drawings','drawMode','drawNote','handrail','unit','order'].forEach(k=>{cur[k]=d[k];});
    $('#sec-drawing .drawing').innerHTML=drawingBodyHtml(cur);
    const pr=$('#paramResults'); if(pr) pr.innerHTML=paramResultsHtml(cur);
    const seq=++renderSeq; setTarget=null; inkMode=null; inkUndo=[];
    views=cur.drawings.map(dw=>({zoom:1,page:1,pages:1,aspect:70,ink:(dw.ink||[]).map(k=>{try{return {id:k.id,page:k.page,by:k.by,d:JSON.parse(k.data)};}catch(e){return null;}}).filter(Boolean)}));
    cur.drawings.forEach((dw,i)=>{renderPoints(i);loadDrawing(i,seq);});
    stepAt=-1;updatePtProg();watchDrawingSection();
    if(cur.drawMode==='none') toast('条件に合う図面がありません。表示内容を確認してください');
    else if(cur.drawMode==='multi') toast('候補が複数あります。表示内容を確認してください');
    else if(needsDrawingReview(cur)) toast('図番の確認が必要です。画面の案内を確認してください');
    else toast('保存済みの情報から図面を表示し直しました');
  } catch(e) { alert('図面を表示し直せませんでした：'+(e.message||e)); }
  finally {loading(false);}
}

function renderNotFound(code) {
  cur = null;
  $('#nav').hidden = true;
  $('#main').className = '';
  $('#main').innerHTML = `<div class="statusbar"><button class="btn" data-act="back">一覧に戻る</button></div>
    <div class="notfound"><b>指示書マスタに登録されていません</b>
    <div>読み取った内容（この値を「指示書マスタ」の指図NO列に登録すると表示されます）</div>
    <code>${esc(code)}</code></div>`;
}

function paramResultsHtml(d) { return `
    ${paramTableHtml(d)}
    ${d.calc && d.calc.length ? `<h4 style="margin:14px 0 6px">計算した値（計算項目シートの式）</h4>
      <table class="tbl"><thead><tr><th>項目</th><th>値</th></tr></thead><tbody>
      ${d.calc.map(c => `<tr><td>${esc(c.name)}</td><td>${c.error ? `<span class="calc-err">計算できません：${esc(c.error)}</span>` : `<b>${esc(c.value)}</b>`}</td></tr>`).join('')}
      </tbody></table>` : ''}
`; }

function needsDrawingReview(d) {
  const p=findParam(d.params||[],'3','器具');
  return d.drawMode==='auto' && d.unit==='U' && /GSUS900JS/i.test(String(p && p.value || '')) && (d.drawings||[]).some(x=>String(x.no||'').toUpperCase()==='K-UTNUA13A');
}

function drawingBodyHtml(d) {
  // 図面を上に。図面の選び直し・再表示・パラメータの一覧は、下の「図面の設定」にまとめる（必要なときだけ開く）
  const req = defsFor(d.unit).filter(x => x.required);
  const miss = req.some(x => { const p = findParam(d.params, x.no, x.name); return !p || !p.value; });
  const open = !d.drawings.length || d.drawMode === 'none' || d.drawMode === 'multi' || needsDrawingReview(d) || miss;
  return `
    <div id="hrBox">${handrailHtml(d)}</div>
    ${needsDrawingReview(d) ? '<div class="dnote ng">⚠ この仕様は03Aとの判定が未確認です。図番と寸法を確認してから作業してください。</div>' : ''}
    ${drawNoteHtml(d)}
    ${d.drawings.map(drawingHtml).join('')}
    <details class="dtools" ${open ? 'open' : ''}><summary><span>図面の設定（選び直し・再表示・判定に使うパラメータ）</span></summary>
      <div class="in"><button class="btn primary" data-act="autoExpand">図面を自動展開</button><button class="btn" data-rule-library="choose">登録済み標準図から選ぶ</button>
        ${d.drawMode === 'auto' || d.drawMode === 'multi' ? '<button class="btn" data-act="tokuzuAdd">特注品なら特図を登録</button>' : ''}
        <span class="note">保存済みパラメータから図面・寸法・印を表示し直します</span></div>
      <div style="padding:0 12px 4px">${paramSummaryHtml(d)}</div>
    </details>
  `;}

function render(d) {
  // 足りない項目があっても画面が止まらないように補う
  d.params = d.params || []; d.parts = d.parts || []; d.quality = d.quality || []; d.work = d.work || [];
  d.drawings = (d.drawings || []).map(dw => Object.assign({ points: [] }, dw));
  d.status = d.status || { state: '未着手', worker: '', startAt: '', doneAt: '' };
  cur = d;
  const o = d.order;
  visual = Array(11).fill(true);

  if (!tabOrder || !same(tabOrder, o['指図NO'])) { wtab = 'drawing'; tabOrder = o['指図NO']; }   // 別の指示書を開いたら図面から
  $('#main').className = 'tabbed';
  $('#main').dataset.tab = wtab;
  $('#main').innerHTML = `
  <div class="workbar">
    <div class="statusbar" id="statusBar"></div>
    <nav class="wtabs" id="wtabs" aria-label="作業の切り替え">
      <button data-wtab="drawing" id="nvDraw"><span>図面</span><b></b></button>
      <button data-wtab="info"><span>指示書</span></button>
      <button data-wtab="params" id="nvParam"><span>パラメータ</span><b></b></button>
      <button data-wtab="quality" id="nvQual"><span>品質記録</span><b></b></button>
      <button data-wtab="work" id="nvWork"><span>完了</span><b></b></button>
      <button data-wtab="parts" class="aux"><span>部品</span>${d.parts.length ? `<b>${d.parts.length}</b>` : ''}</button>
    </nav>
  </div>

  <section class="card" id="sec-info"><details open><summary>指示書</summary><div class="body">
    <div class="info-grid">${INFO_KEYS.filter(k => o[k]).map(k => `<div><span>${esc(k)}</span><b>${esc(o[k])}</b></div>`).join('')}</div>
    <div class="scanned">読取値：${esc(d.scanned)}</div>
    ${o['指示書PDF'] ? `<details open style="margin-top:8px"><summary style="font-size:15px;padding:8px 0;background:none;border:0">指示書の原本
        <button class="btn sm" data-docrot="shiji" style="margin-left:auto">回転</button></summary>
      <div class="docv" data-doc="${esc(o['指示書PDF'])}" data-kind="shiji"><p class="note">読み込み中…</p></div></details>` : ''}
  </div></details></section>

  <section class="card" id="sec-drawing"><details open><summary>図面と見るところ <span class="badge" id="ptProg"></span></summary><div class="body drawing">
    ${drawingBodyHtml(d)}
  </div></details></section>

  <section class="card" id="sec-params"><details open><summary>パラメータ ${o['パラメータ文字列'] ? `<span class="badge">${esc(o['パラメータ文字列'])}</span>` : ''}</summary><div class="body">
    ${o['パラメータ表PDF'] ? `<details open><summary style="font-size:15px;padding:8px 0;background:none;border:0">パラメータ表の原本
        <button class="btn sm" data-docrot="param" style="margin-left:auto">回転</button></summary>
      <div class="docv" data-doc="${esc(o['パラメータ表PDF'])}" data-kind="param"><p class="note">読み込み中…</p></div></details>` : ''}
    <div id="paramResults">${paramResultsHtml(d)}</div>
    <button class="btn primary" data-act="paramEdit" id="btnParamEdit">パラメータを入力・修正</button>
    <div id="pformBox"></div>
  </div></details></section>

  <section class="card" id="sec-quality"><details open><summary>品質記録 <span class="badge" id="qCount"></span></summary><div class="body">
    <div class="form">
      <label>検査日<input type="date" id="qDate" value="${today()}"></label>
      <label>品番<input id="qHinban" value="${esc(o['組立品番'])}"></label>
      <label>フロア<input id="qFloor" value="${esc(o['適用階'])}"></label>
      <div class="field">ユニット位置${seg('qPos', ['左','中','右'])}</div>
      <div class="field">寸法${seg('qSize', ['合','否'], '合')}</div>
      <div class="field wide">外観（NGの番号をタップ）<div class="visual" id="qVisual"></div></div>
      <label>検査者${nameInput('qInspector', getMe())}</label>
      <label>責任者${nameInput('qManager', '', 'managerNames')}</label>
      <label class="wide">備考<input id="qNote"></label>
      <button class="btn primary big wide" data-act="saveQuality">品質記録を保存</button>
    </div>
    <div class="hist" id="qList"></div>
  </div></details></section>

  <section class="card" id="sec-work"><details open><summary>作業実績 <span class="badge" id="wCount"></span></summary><div class="body">
    <div id="doneCheck"></div>
    <div class="form">
      <label>完了日<input type="date" id="wDate" value="${today()}"></label>
      <label>組立完了台数<input type="number" inputmode="numeric" min="0" id="wQty" value="${esc(o['組立台数'] || '')}"></label>
      <label>取揃担当${nameInput('wPicker', '')}</label>
      <label>組立担当${nameInput('wAssembler', getMe())}</label>
      <label class="wide">備考<input id="wNote"></label>
      <button class="btn primary big wide" data-act="saveWork">作業実績を保存して完了にする</button>
    </div>
    <div class="hist" id="wList"></div>
  </div></details></section>

  <section class="card" id="sec-parts"><details><summary>部品一覧（参考） <span class="badge">${d.parts.length}点</span></summary><div class="body">
    <button class="btn" data-act="parts" style="margin-bottom:10px">部品リストを大きく表示</button>
    ${d.parts.length ? `<table class="tbl parts">
      <thead><tr><th>行</th><th>棚番</th><th>品番 / 品名</th><th>数</th></tr></thead>
      <tbody>${d.parts.map(p => `<tr>
        <td>${esc(p.rowNo)}</td><td class="mono">${esc(p.tana)}</td>
        <td><span class="mono">${esc(p.hinban)}</span><br><small>${esc(p.name)}</small></td>
        <td class="num">${esc(p.qty)}${p.doukon ? `<br><small>同梱${esc(p.doukon)}</small>` : ''}</td></tr>`).join('')}</tbody></table>`
      : '<p class="note">部品明細は登録されていません</p>'}
  </div></details></section>`;

  renderStatus();
  renderVisual();
  const seq = ++renderSeq;
  setTarget = null;
  inkMode = null; inkUndo = [];
  views = d.drawings.map(dw => ({
    zoom: 1, page: 1, pages: 1, aspect: 70,
    ink: (dw.ink || []).map(k => { try { return { id: k.id, page: k.page, by: k.by, d: JSON.parse(k.data) }; } catch (e) { return null; } }).filter(Boolean),
  }));
  d.drawings.forEach((dw, i) => { renderPoints(i); loadDrawing(i, seq); });
  loadDocs(seq);
  renderQualityList(d.quality);
  renderWorkList(d.work);
  stepAt = -1;
  updatePtProg();
  watchDrawingSection();
  setTab(wtab, true);
}

/* ---------- 図面と見るところ ---------- */
function drawNoteHtml(d) {
  const bad = (d.drawings || []).flatMap(dw => (dw.points || []).filter(p => p.applies && p.calcError));
  const warn = bad.length ? `<div class="dnote ng">⚠ 書き込む値を計算できない箇所が ${bad.length} か所あります（番号 ${bad.map(p => p.no).join('・')}）。
    パラメータが寸法表に無い値か、入力漏れの可能性があります。図面に「？」と出ている所は、自分で決めずに責任者に確認してください。</div>` : '';
  return warn + drawNoteHtml0(d);
}
function drawNoteHtml0(d) {
  if (d.drawMode === 'none') return `<div class="dnote ng">⚠ ${esc(d.drawNote)}
    <div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap">
      <button class="btn primary sm" data-act="paramEdit">標準品：パラメータを入力</button>
      <button class="btn primary sm" data-act="tokuzuAdd">特注品：特図を登録</button></div></div>`;
  if (d.drawMode === 'multi') return `<div class="dnote warn">⚠ ${esc(d.drawNote)}</div>`;
  if (d.drawMode === 'auto') return `<div class="dnote ok">パラメータから自動で選んだ標準図です。番号の順に、赤枠の場所を確認してください。</div>`;
  const tk = d.drawings.some(x => x.tokuzu);
  return `<div class="dnote ok" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
    <span style="flex:1">${tk ? `特注品：この指示書専用の特図です。${d.autoTokuzu ? `（特図フォルダの「${esc(d.autoTokuzu)}」を自動でつなぎました）` : ''}` : '指示書に指定された図面です。'}</span>
    <button class="btn sm" data-act="tokuzuAdd">特図を差し替え</button>
    ${tk ? '<button class="btn sm danger" data-act="tokuzuClear">つながりを外す</button>' : ''}</div>`;
}

function drawingHtml(dw, i) {
  const head = `<div class="dw-head"><b>${esc(dw.no)} ${esc(dw.name)}</b><div class="note">${esc(dw.reason || '')}</div></div>`;
  if (!dw.url) {
    return `<div class="dw">${head}<ol class="pts" id="pts-${i}"></ol>
      <p class="note">「組図マスタ」にこの図面のPDF（GoogleドライブのURL）を登録すると、ここに表示されます。</p></div>`;
  }
  return `<div class="dw" id="dw-${i}">${head}
    <div class="vtools">
      <button class="btn sm" data-zoom="${i}" data-dz="-1">－</button>
      <span class="zl" id="zl-${i}">100%</span>
      <button class="btn sm" data-zoom="${i}" data-dz="1">＋</button>
      <span id="pg-${i}"></span>
      <span class="grow"></span>
      <button class="btn sm" data-inkbtn="${i}">書き込み</button>
      ${dw.no ? `<button class="btn sm" data-movebtn="${i}">印を動かす</button>` : ''}
      <button class="btn sm" data-expand="${i}">展開図</button>
      <a class="btn sm" href="${esc(dw.url)}" target="_blank" rel="noopener">別画面で開く</a>
      ${dw.no ? `<button class="btn sm ${adminPin ? 'admin-on' : ''}" data-admin="${i}">位置設定</button>` : ''}
    </div>
    <div class="inkbar" id="ib-${i}" hidden></div>
    <div class="viewer" id="vw-${i}"><div class="stage" id="st-${i}"><div class="vmsg">図面を読み込み中…</div></div></div>
    <details class="points-section" id="pointDetails-${i}"><summary>確認ポイント・寸法入力を開く</summary><ol class="pts" id="pts-${i}"></ol></details>
  </div>`;
}

const hasPos = p => p.x != null && p.y != null && p.w != null && p.h != null;
const shown = p => p.applies || adminPin;      // 設定モードでは対象外のポイントも表示

function renderPoints(i) {
  const ol = $('#pts-' + i);
  if (!ol) return;
  const dw = cur.drawings[i], v = views[i] || {};
  const list = dw.points.map((p, j) => ({ p, j })).filter(x => shown(x.p));
  if (!list.length) { ol.innerHTML = dw.no ? '<li class="note">この図面の見るところは登録されていません</li>' : ''; return; }
  ol.innerHTML = list.map(({ p, j }) => `
    <li class="pt ${p.style === 'marker' ? 'mk' : ''} ${p.important ? 'imp' : ''} ${p.confirmed ? 'ok' : ''} ${p.applies ? '' : 'na'} ${v.focus === j ? 'focus' : ''}" data-pt="${i}:${j}">
      <span class="pno">${esc(p.no)}</span>
      <div class="ptxt">${esc(p.text)}${p.important ? '<em>重要</em>' : ''}
        ${p.write ? `<br><b class="wv">${p.overridden ? '手入力値' : '記入値'} ${esc(p.write)}</b>${p.overridden ? `<small>自動計算値 ${esc(p.baseWrite)}（手入力で変更）</small>` : ''}` : ''}${p.overrideStale ? '<small class="calc-warn">パラメータが変わったため手入力値を外しました。寸法を再確認してください</small>' : ''}
        ${p.calcError && p.applies ? `<small class="calc-warn">⚠ ${esc(p.calcError)}。図面と指示書で確認し、責任者に相談してください</small>` : ''}
        ${p.applies ? '' : '<small>このパラメータでは対象外（設定モードのみ表示）</small>'}
        ${adminPin && p.cond ? `<small>条件：${esc(p.cond)}</small>` : ''}
        ${hasPos(p) ? '' : '<small>図面上の位置は未登録</small>'}
        ${p.confirmed ? `<small class="who">確認済 ${esc(p.by)} ${esc(p.at)}</small>` : ''}</div>
      ${v.moveMode && p.applies && (p.style === 'marker' || p.write || p.manualKey) && hasPos(p) ? `<span style="display:flex;gap:2px" aria-label="印の位置を調整"><button class="btn sm" data-nudge="${i}:${j}:-0.5:0" aria-label="左に移動">←</button><button class="btn sm" data-nudge="${i}:${j}:0:-0.5" aria-label="上に移動">↑</button><button class="btn sm" data-nudge="${i}:${j}:0:0.5" aria-label="下に移動">↓</button><button class="btn sm" data-nudge="${i}:${j}:0.5:0" aria-label="右に移動">→</button></span>` : ''}
      ${p.manualKey && p.applies && !adminPin ? `<label style="display:flex;align-items:center;gap:4px">${p.manualKey}端 <input type="number" min="0.01" step="0.01" inputmode="decimal" data-manual-value="${i}:${j}" value="${esc(p.write || '')}" aria-label="${p.manualKey}端寸法（mm）" style="width:88px;padding:8px;border:1px solid #888;border-radius:4px">mm</label><button class="btn sm primary" data-manual="${i}:${j}">保存</button>` : ''}

      ${p.baseWrite && !p.linkedPitch && p.applies && !adminPin ? `<label style="display:flex;align-items:center;gap:4px">変更値 <input type="number" min="0.01" step="0.01" inputmode="decimal" data-dim-value="${i}:${j}" value="${esc(p.write || '')}" aria-label="寸法の変更値" style="width:80px;padding:8px;border:1px solid #888;border-radius:4px">mm</label><button class="btn sm primary" data-dim-save="${i}:${j}">寸法を保存</button><button class="btn sm" data-dim-reset="${i}:${j}">自動値に戻す</button>` : ''}
      ${adminPin ? `<button class="btn sm" data-setpos="${i}:${j}">${hasPos(p) ? '位置を変更' : '位置を登録'}</button>`
        : p.applies ? `<button class="btn sm ${p.confirmed ? 'okbtn' : ''}" data-ptok="${i}:${j}">${p.confirmed ? '✔ 確認済' : '確認'}</button>` : ''}
    </li>`).join('');
}

function updatePtProg() {
  const all = cur.drawings.flatMap(dw => dw.points.filter(p => p.applies));
  if (cur.handrail) all.unshift(cur.handrail);   // U はテスリの確認も数える
  const ok = all.filter(p => p.confirmed).length;
  const b = $('#ptProg');
  if (!b) return;
  b.textContent = all.length ? `確認 ${ok} / ${all.length}` : '';
  b.classList.toggle('ok', all.length > 0 && ok === all.length);
  updateProgress();
}

/* ---------- 作業モードのタブ（図面／指示書／パラメータ／品質記録／完了／部品） ---------- */
let wtab = 'drawing', tabOrder = '';
const TAB_OF = { 'sec-drawing': 'drawing', 'hrBox': 'drawing', 'sec-info': 'info', 'sec-params': 'params', 'pformBox': 'params',
  'sec-quality': 'quality', 'sec-work': 'work', 'doneCheck': 'work', 'sec-parts': 'parts' };
function setTab(t, keepScroll) {
  const main = $('#main');
  if (!main || !$('#wtabs')) return;
  wtab = t;
  main.dataset.tab = t;
  document.querySelectorAll('#wtabs [data-wtab]').forEach(b => b.classList.toggle('on', b.dataset.wtab === t));
  main.querySelectorAll(':scope > section.card').forEach(x => x.classList.toggle('off', x.id !== 'sec-' + t));
  const sec = $('#sec-' + t);
  const det = sec && sec.querySelector(':scope > details');
  if (det) det.open = true;
  if (!keepScroll) window.scrollTo({ top: 0 });
  stepVisible = t === 'drawing';
  updateStepper();
  if (t === 'drawing') views.forEach((_, i) => { if ($('#st-' + i)) applyZoom(i); });
}
// 画面の中の場所（欄・テスリ・入力フォームなど）を、タブを切り替えてから見せる
function showPlace(el, block) {
  if (!el) return;
  const key = Object.keys(TAB_OF).find(id => el.id === id || el.closest('#' + id));
  if (key && TAB_OF[key] !== wtab) setTab(TAB_OF[key], true);
  if (/^sec-/.test(el.id)) return window.scrollTo({ top: 0, behavior: 'smooth' });
  el.scrollIntoView({ behavior: 'smooth', block: block || 'start' });
}

/* ---------- 作業の進み具合（目次・完了チェック） ---------- */
function progressOf() {
  const pts = cur.drawings.flatMap(dw => dw.points.filter(p => p.applies));
  const ptOk = pts.filter(p => p.confirmed).length;
  const req = defsFor(cur.unit).filter(x => x.required);
  const pMiss = req.filter(x => { const p = findParam(cur.params, x.no, x.name); return !p || !p.value; }).length;
  const qty = parseInt(String(cur.order['組立台数'] || '').replace(/[^\d]/g, ''), 10) || 1;
  return { pts: pts.length, ptOk, pMiss, q: (cur.quality || []).length, qty, hr: cur.handrail, work: (cur.work || []).length };
}

function setNav(id, text, cls) {
  const b = $('#' + id + ' b');
  if (!b) return;
  b.textContent = text || '';
  b.className = cls || '';
}

function updateProgress() {
  if (!cur || !$('#doneCheck')) return;
  const g = progressOf();
  const hrLeft = g.hr && !g.hr.confirmed ? 1 : 0;
  setNav('nvDraw', g.pts || g.hr ? `${g.ptOk + (g.hr && g.hr.confirmed ? 1 : 0)}/${g.pts + (g.hr ? 1 : 0)}` : '',
    g.ptOk === g.pts && !hrLeft ? 'ok' : 'ng');
  setNav('nvParam', g.pMiss ? `未入力${g.pMiss}` : '', 'ng');
  setNav('nvQual', `${g.q}/${g.qty}台`, g.q >= g.qty ? 'ok' : 'ng');
  setNav('nvWork', g.work ? '済' : '', 'ok');

  // 作業実績の上に「完了の前に残っているもの」
  const items = [];
  if (g.hr) items.push({ ok: !hrLeft, href: '#hrBox', t: hrLeft ? 'テスリをまだ確認していません' : 'テスリを確認済み' });
  if (g.pts) items.push({ ok: g.ptOk === g.pts, href: '#sec-drawing', t: g.ptOk === g.pts ? `図面の見るところ ${g.pts}か所を確認済み` : `図面の見るところ 残り${g.pts - g.ptOk}か所（${g.ptOk}/${g.pts}）` });
  items.push({ ok: g.q >= g.qty, href: '#sec-quality', t: `品質記録 ${g.q}/${g.qty}台` });
  const all = items.every(x => x.ok);
  $('#doneCheck').innerHTML = `<div class="donechk ${all ? 'ok' : ''}">
    <b>${all ? 'すべて確認済みです。作業実績を保存すると完了です' : '完了の前に残っているもの'}</b>
    <ul>${items.map(x => `<li class="${x.ok ? 'ok' : ''}"><a href="${x.href}">${esc(x.t)}</a></li>`).join('')}</ul></div>`;
  updateStepper();
}

/* ---------- 見るところを順番に確認（画面下のバー） ---------- */
let stepAt = -1;          // 今見ている見るところ（steps() の番号）
let stepVisible = false;  // 図面の欄が画面に入っているか
let stepTick = 0;

function steps() {
  if (!cur) return [];
  return cur.drawings.flatMap((dw, i) => dw.points.map((p, j) => ({ i, j, p })).filter(x => x.p.applies));
}

// 図面の欄が画面の4割以上を占めている間だけ、バーを出す
function checkDrawingInView() {
  stepTick = 0;
  const sec = view === 'detail' && $('#sec-drawing');
  let vis = false;
  if (sec) {
    const r = sec.getBoundingClientRect();
    vis = Math.min(r.bottom, window.innerHeight) - Math.max(r.top, 0) > window.innerHeight * 0.4;
  }
  vis = view === 'detail' && wtab === 'drawing';
  if (vis !== stepVisible) { stepVisible = vis; updateStepper(); }
}
function watchDrawingSection() {
  stepVisible = false;
  delete $('#stepper').dataset.review;
  checkDrawingInView();
  updateStepper();
}
window.addEventListener('scroll', () => { if (!stepTick) stepTick = requestAnimationFrame(checkDrawingInView); }, { passive: true });
window.addEventListener('resize', () => { if (!stepTick) stepTick = requestAnimationFrame(checkDrawingInView); });

function updateStepper() {
  const bar = $('#stepper');
  if (!bar) return;
  const list = steps();
  const show = view === 'detail' && stepVisible && list.length > 0 && !inkMode && !adminPin && $('#partsView').hidden;
  bar.hidden = !show;
  document.body.classList.toggle('has-stepper', show);
  if (!show) return;
  if (stepAt < 0 || stepAt >= list.length) {
    stepAt = Math.max(0, list.findIndex(x => !x.p.confirmed));
  }
  const left = list.filter(x => !x.p.confirmed).length;
  if (!left && !bar.dataset.review) {
    bar.innerHTML = `<div class="sp-all"><span>図面の見るところは、すべて確認済みです（${list.length}か所）</span>
      <span style="display:flex;gap:8px"><button class="btn sm" data-stepreview style="background:var(--ink-2);color:#fff;border-color:var(--ink-3)">見直す</button>
      <a class="btn" href="#sec-quality">品質記録へ</a></span></div>`;
  } else {
    const { p } = list[stepAt];
    bar.innerHTML = `<div class="sp-in">
      <span class="pno ${p.confirmed ? 'ok' : p.style === 'marker' ? 'mk' : ''}">${esc(p.no)}</span>
      <div class="sp-txt" data-stepfocus><span>${p.important ? '<em>重要</em>' : ''}${esc(p.text)}</span>
        ${p.write ? `<b class="wv">記入値 ${esc(p.write)}</b>` : ''}</div>
      <span class="sp-cnt"><b>${stepAt + 1}</b> / ${list.length}<br>残り${left}</span>
      <div class="sp-btns">
        <button data-step="-1" aria-label="前の見るところ">◀</button>
        <button class="go ${p.confirmed ? 'done' : ''}" data-stepok>${p.confirmed ? '✔ 確認済み・次へ' : '確認して次へ'}</button>
        <button data-step="1" aria-label="次の見るところ">▶</button>
      </div></div>`;
  }
  document.documentElement.style.setProperty('--sp-h', bar.offsetHeight + 'px');
}

async function stepGo(k) {
  const list = steps();
  if (!list.length) return;
  stepAt = (k + list.length) % list.length;
  const { i, j } = list[stepAt];
  updateStepper();
  await focusPoint(i, j);
}

async function stepOk() {
  const list = steps();
  const x = list[stepAt];
  if (!x) return;
  if (!x.p.confirmed) {
    await togglePoint(x.i, x.j);
    if (!x.p.confirmed) return;   // 作業開始を断ったときなど
  }
  // 次の未確認へ（無ければ全部確認済みの表示）
  const n = list.length;
  for (let d = 1; d <= n; d++) {
    const k = (stepAt + d) % n;
    if (!list[k].p.confirmed) return stepGo(k);
  }
  delete $('#stepper').dataset.review;
  updateStepper();
}

function onStepperClick(e) {
  if (e.target.closest('[data-stepok]')) return stepOk();
  const s = e.target.closest('[data-step]');
  if (s) return stepGo(stepAt + Number(s.dataset.step));
  if (e.target.closest('[data-stepfocus]')) return stepGo(stepAt);
  if (e.target.closest('[data-stepreview]')) { $('#stepper').dataset.review = '1'; stepAt = 0; return stepGo(0); }
}

function base64ToBytes(b64) {
  const bin = atob(b64), out = new Uint8Array(bin.length);
  for (let k = 0; k < bin.length; k++) out[k] = bin.charCodeAt(k);
  return out;
}

async function loadDrawing(i, seq) {
  const dw = cur.drawings[i];
  if (!dw.url) return;
  const v = views[i];
  const first = dw.points.find(p => p.applies && hasPos(p));
  if (first) v.page = first.page;
  try {
    if (!dw.preview) throw new Error('GoogleドライブのURLではありません');
    let f = fileCache[dw.url];
    if (!f) f = fileCache[dw.url] = await run('getDrawingFile', dw.url);
    if (seq !== renderSeq) return;
    const bytes = base64ToBytes(f.data);
    if (/pdf/i.test(f.mime)) {
      if (!window.pdfjsLib) throw new Error('PDF表示の部品を読み込めませんでした');
      v.pdf = await pdfjsLib.getDocument({ data: bytes }).promise;
      v.pages = v.pdf.numPages;
    } else if (/^image\//i.test(f.mime)) {
      v.img = await loadImage(new Blob([bytes], { type: f.mime }));
    } else {
      throw new Error('PDFか画像の図面だけ赤枠表示できます');
    }
    if (seq !== renderSeq) return;
    await renderPage(i);
  } catch (e) {
    if (seq !== renderSeq) return;
    const st = $('#st-' + i);
    if (st) st.innerHTML = (dw.preview ? `<iframe src="${esc(dw.preview)}" allow="autoplay"></iframe>` : '') +
      `<p class="note" style="padding:8px">赤枠つきで表示できませんでした（${esc(e.message)}）。番号のリストを見ながら図面を確認してください。</p>`;
  }
}

async function renderPage(i) {
  const v = views[i], st = $('#st-' + i);
  if (!st) return;
  if (v.page > v.pages) v.page = 1;
  st.innerHTML = `<canvas></canvas><div class="layer" id="ly-${i}"></div><svg class="ink" id="ink-${i}" xmlns="http://www.w3.org/2000/svg"></svg>`;
  const cv = st.querySelector('canvas');
  // 拡大しても読めるよう、表示幅の2倍程度（最大3000px）で描く。大きく拡大したら sharpen() で描き直す
  const targetW = Math.min(3000, Math.max(1600, st.parentElement.clientWidth * (window.devicePixelRatio || 1) * 2));
  await drawPageTo(v, cv, targetW);
  v.aspect = cv.height / cv.width * 100;   // 書き込みの座標：横0〜100、縦0〜aspect（拡大してもずれない）
  $('#ink-' + i).setAttribute('viewBox', `0 0 100 ${v.aspect}`);
  st.style.width = (v.zoom * fitBase(i) * 100) + '%';
  attachSetting(i);
  attachPointMove(i);
  attachInk(i);
  attachPinch(i);
  applyZoom(i);
  renderBoxes(i);
  renderInk(i);
  const pg = $('#pg-' + i);
  if (pg) pg.innerHTML = v.pages > 1 ? `<button class="btn sm" data-page="${i}" data-dp="-1">◀</button> ${v.page}/${v.pages} <button class="btn sm" data-page="${i}" data-dp="1">▶</button>` : '';
}

// 図面のページを、指定の横幅（px）でキャンバスに描く
async function drawPageTo(v, cv, targetW) {
  if (v.pdf) {
    const page = await v.pdf.getPage(v.page);
    const vp = page.getViewport({ scale: targetW / page.getViewport({ scale: 1 }).width });
    cv.width = Math.round(vp.width); cv.height = Math.round(vp.height);
    await page.render({ canvasContext: cv.getContext('2d'), viewport: vp }).promise;
  } else if (v.img) {
    const sc = Math.min(1, targetW / v.img.naturalWidth);
    cv.width = Math.round(v.img.naturalWidth * sc); cv.height = Math.round(v.img.naturalHeight * sc);
    cv.getContext('2d').drawImage(v.img, 0, 0, cv.width, cv.height);
  }
}

// 大きく拡大したとき、細かい文字がぼやけないよう、その拡大率に合わせて描き直す（最大 4096px）
async function sharpen(i) {
  const v = views[i], st = $('#st-' + i);
  const old = st && st.querySelector('canvas');
  if (!old || !(v.pdf || v.img)) return;
  const need = Math.min(4096, Math.round(st.clientWidth * (window.devicePixelRatio || 1)));
  if (need <= old.width * 1.25) return;
  const page = v.page, cv = document.createElement('canvas');
  await drawPageTo(v, cv, need);
  if (v.page !== page || !old.isConnected) return;   // 途中でページが変わったら使わない
  old.replaceWith(cv);
  old.width = old.height = 0;   // 古い画像のメモリを空ける
}

/* ---------- 指でつまんで拡大・2本指で移動（書き込み中も使える） ---------- */
function setZoomAt(i, zoom, clientX, clientY) {
  const v = views[i], vw = $('#vw-' + i), st = $('#st-' + i);
  if (!vw || !st) return;
  zoom = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, zoom));
  const r = vw.getBoundingClientRect();
  const px = clientX - r.left, py = clientY - r.top;
  // 指の下にある図面の位置（割合）を覚えて、拡大後も同じ場所が指の下に来るようにする
  const fx = (vw.scrollLeft + px) / st.offsetWidth, fy = (vw.scrollTop + py) / st.offsetHeight;
  v.zoom = zoom;
  st.style.width = (zoom * 100) + '%';
  vw.scrollLeft = fx * st.offsetWidth - px;
  vw.scrollTop = fy * st.offsetHeight - py;
  const zl = $('#zl-' + i);
  if (zl) zl.textContent = Math.round(zoom * 100) + '%';
}

function attachPinch(i) {
  const vw = $('#vw-' + i);
  if (!vw || vw.dataset.pinch) return;
  vw.dataset.pinch = '1';
  const v = views[i];
  let g = null, raf = 0, sharpTimer = 0;
  const mid = t => ({ x: (t[0].clientX + t[1].clientX) / 2, y: (t[0].clientY + t[1].clientY) / 2 });
  const dist = t => Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY) || 1;
  vw.addEventListener('touchstart', e => {
    if (e.touches.length !== 2) return;
    e.preventDefault();
    if (v.cancelInk) v.cancelInk();   // 1本目の指で書き始めていた線は消す
    v.pinch = true;
    const m = mid(e.touches);
    g = { d: dist(e.touches), zoom: v.zoom, mx: m.x, my: m.y };
  }, { passive: false });
  vw.addEventListener('touchmove', e => {
    if (!g || e.touches.length !== 2) return;
    e.preventDefault();
    const t = [e.touches[0], e.touches[1]];
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      const m = mid(t);
      vw.scrollLeft -= m.x - g.mx;   // 2本指でずらすと図面が動く
      vw.scrollTop -= m.y - g.my;
      g.mx = m.x; g.my = m.y;
      setZoomAt(i, g.zoom * dist(t) / g.d, m.x, m.y);
    });
  }, { passive: false });
  const end = e => {
    if (!g || e.touches.length >= 2) return;
    g = null;
    renderBoxes(i);   // 枠の数字の大きさを、拡大率に合わせ直す
    clearTimeout(sharpTimer);
    sharpTimer = setTimeout(() => sharpen(i), 250);
    // 指が全部離れるまでは、書き込みを始めない
    if (e.touches.length === 0) v.pinch = false;
  };
  vw.addEventListener('touchend', end);
  vw.addEventListener('touchcancel', end);
  const release = e => { if (e.touches.length === 0) v.pinch = false; };
  vw.addEventListener('touchend', release);
  vw.addEventListener('touchcancel', release);
  // PC：Ctrl＋ホイール（ノートPCのタッチパッドで2本指で広げる操作も同じ）で拡大
  vw.addEventListener('wheel', e => {
    if (!e.ctrlKey) return;
    e.preventDefault();
    setZoomAt(i, v.zoom * Math.exp(-e.deltaY * 0.01), e.clientX, e.clientY);
    clearTimeout(sharpTimer);
    sharpTimer = setTimeout(() => { renderBoxes(i); sharpen(i); }, 250);
  }, { passive: false });
}

// 100%のとき、図面の全体が画面（図面の枠）に入る大きさにする。横長の画面で下が切れないように
function fitBase(i) {
  const vw = $('#vw-' + i), v = views[i];
  if (!vw || !v || !v.aspect || !vw.clientHeight || !vw.clientWidth) return 1;
  return Math.max(0.3, Math.min(1, (vw.clientHeight - 4) / (vw.clientWidth * v.aspect / 100)));
}
function applyZoom(i) {
  const v = views[i], st = $('#st-' + i);
  if (!st) return;
  st.style.width = (v.zoom * fitBase(i) * 100) + '%';
  const zl = $('#zl-' + i);
  if (zl) zl.textContent = Math.round(v.zoom * 100) + '%';
  if ($('#ly-' + i)) renderBoxes(i);
}

function renderBoxes(i) {
  const ly = $('#ly-' + i);
  if (!ly) return;
  const v = views[i];
  const tmp = ly.querySelector('.tmp');
  const sh = ly.clientHeight;   // 書き込みの文字の大きさは枠の高さに合わせる（拡大すると一緒に大きくなる）
  ly.innerHTML = cur.drawings[i].points.map((p, j) => (shown(p) && hasPos(p) && p.page === v.page) ? `
    <div class="box st-${p.style || 'box'} ${p.write ? 'wr' : ''} ${p.confirmed ? 'ok' : ''} ${p.applies ? '' : 'na'} ${v.focus === j ? 'focus' : ''}" data-box="${i}:${j}"
      style="left:${p.x}%;top:${p.y}%;width:${p.w}%;height:${p.h}%"><span class="bno">${esc(p.no)}</span>
      ${p.write ? `<span class="wtxt" style="font-size:${Math.max(7, sh * p.h / 100 * ((cur.drawings[i].no === 'K-UTNUA03A' && [13,14,15,16].includes(Number(p.no))) ? 0.38 : 0.85))}px">${esc(p.write)}</span>` : ''}</div>` : '').join('');
  if (tmp) ly.appendChild(tmp);
  ly.classList.toggle('setting', !!(setTarget && setTarget.i === i));
  ly.classList.toggle('moving', !!v.moveMode);
}


function togglePointMove(i) {
  if (!getMe()) return needStaff();
  const v=views[i]; if (!v || !$('#ly-'+i)) return alert('図面が表示されてから操作してください');
  if (adminPin) return alert('位置設定を終了してから操作してください');
  if (inkMode) toggleInk(inkMode.i);
  v.moveMode=!v.moveMode;
  const details=$('#pointDetails-'+i); if(details && v.moveMode) details.open=true;
  const btn=document.querySelector('[data-movebtn="'+i+'"]');
  if (btn) { btn.textContent=v.moveMode?'移動を終了':'印を動かす'; btn.classList.toggle('admin-on',v.moveMode); }
  renderPoints(i); renderBoxes(i); toast(v.moveMode?'緑の印を指やマウスで移動できます':'印の移動を終了しました');
}
async function nudgePoint(i,j,dx,dy) {
  const p=cur.drawings[i].points[j], dw=cur.drawings[i]; if (!p || !p.applies || !(p.style==='marker' || p.write || p.manualKey) || !hasPos(p)) return;
  const x=Math.round(Math.max(0,Math.min(100-Number(p.w),Number(p.x)+dx))*100)/100;
  const y=Math.round(Math.max(0,Math.min(100-Number(p.h),Number(p.y)+dy))*100)/100;
  try { await run('savePointMove',cur.order['指図NO'],dw.no,p.no,x,y,getMe()); p.x=x;p.y=y;p.confirmed=false;p.by='';p.at='';renderPoints(i);renderBoxes(i);updatePtProg();toast('この指示書の印の位置を保存しました'); }
  catch(e) { alert('位置を保存できませんでした：'+e.message); }
}
function attachPointMove(i) {
  const ly=$('#ly-'+i); let drag=null;
  ly.addEventListener('pointerdown',e=>{
    const v=views[i], box=e.target.closest('[data-box]');
    if(!v.moveMode || !box || !(box.classList.contains('st-marker') || box.classList.contains('wr')) || !e.isPrimary) return;
    const parts=box.dataset.box.split(':').map(Number), p=cur.drawings[i].points[parts[1]];
    if(!p || !p.applies || !hasPos(p)) return;
    const r=ly.getBoundingClientRect(); if(!r.width || !r.height) return;
    drag={el:box,p,startX:e.clientX,startY:e.clientY,x:Number(p.x),y:Number(p.y),w:r.width,h:r.height};
    box.setPointerCapture(e.pointerId); e.preventDefault(); e.stopPropagation();
  });
  ly.addEventListener('pointermove',e=>{
    if(!drag) return; e.preventDefault(); e.stopPropagation();
    const p=drag.p, nx=Math.max(0,Math.min(100-Number(p.w),drag.x+(e.clientX-drag.startX)*100/drag.w)), ny=Math.max(0,Math.min(100-Number(p.h),drag.y+(e.clientY-drag.startY)*100/drag.h));
    drag.nx=Math.round(nx*100)/100; drag.ny=Math.round(ny*100)/100;
    drag.el.style.left=drag.nx+'%'; drag.el.style.top=drag.ny+'%';
  });
  async function end(e) {
    if(!drag) return; e.preventDefault(); e.stopPropagation();
    const d=drag; drag=null; views[i].suppressClick=true;
    if(d.nx===undefined || (d.nx===d.x && d.ny===d.y)) { renderBoxes(i); return; }
    const p=d.p, dw=cur.drawings[i];
    try { await run('savePointMove',cur.order['指図NO'],dw.no,p.no,d.nx,d.ny,getMe()); p.x=d.nx;p.y=d.ny;p.confirmed=false;p.by='';p.at='';renderPoints(i);renderBoxes(i);updatePtProg();toast('この指示書の印の位置を保存しました'); }
    catch(err) { renderBoxes(i); alert('位置を保存できませんでした：'+err.message); }
  }
  ly.addEventListener('pointerup',end); ly.addEventListener('pointercancel',e=>{if(!drag)return;drag=null;renderBoxes(i);});
}

// 番号をタップ → その場所まで拡大・移動して点滅
async function focusPoint(i, j) {
  const v = views[i], p = cur.drawings[i].points[j];
  v.focus = j;
  const k = steps().findIndex(x => x.i === i && x.j === j);
  if (k >= 0 && k !== stepAt) { stepAt = k; updateStepper(); }
  renderPoints(i);
  if (!hasPos(p) || !$('#ly-' + i)) {
    renderBoxes(i);
    const details=$('#pointDetails-'+i); if(details) details.open=true;
    const li = document.querySelector(`[data-pt="${i}:${j}"]`);   // 位置が未登録なら一覧の行を見せる
    if (li) li.scrollIntoView({ behavior: 'smooth', block: 'center' });
    return;
  }
  if (p.page !== v.page) { v.page = p.page; await renderPage(i); }
  if (v.zoom < 2) { v.zoom = 2; applyZoom(i); }
  renderBoxes(i);
  const vw = $('#vw-' + i), st = $('#st-' + i);
  vw.scrollIntoView({ behavior: 'smooth', block: 'center' });
  vw.scrollLeft = (p.x + p.w / 2) / 100 * st.clientWidth - vw.clientWidth / 2;
  vw.scrollTop = (p.y + p.h / 2) / 100 * st.clientHeight - vw.clientHeight / 2;
}

function zoomBy(i, dz) {
  const v = views[i];
  const k = Math.max(0, Math.min(ZOOMS.length - 1, ZOOMS.findIndex(z => z >= v.zoom) + dz));
  const vw = $('#vw-' + i);
  const cx = (vw.scrollLeft + vw.clientWidth / 2) / vw.scrollWidth, cy = (vw.scrollTop + vw.clientHeight / 2) / vw.scrollHeight;
  v.zoom = ZOOMS[k];
  applyZoom(i);
  vw.scrollLeft = cx * vw.scrollWidth - vw.clientWidth / 2;   // 拡大しても見ている場所を保つ
  vw.scrollTop = cy * vw.scrollHeight - vw.clientHeight / 2;
  setTimeout(() => sharpen(i), 250);
}

// 作業開始していなければ、開始してから確認させる
async function ensureStarted() {
  const staff = needStaff();
  if (!staff) return '';
  const s = cur.status;
  if (s.state === '完了') { alert('この指示書は完了済みです'); return ''; }
  if (s.state === '作業中' && s.worker !== staff) { alert(`${s.worker}さんが作業中の指示書です`); return ''; }
  if (s.state === '未着手') {
    if (!confirm('この指示書の作業を開始しますか？')) return '';
    const r = await doStart(cur.order['指図NO']);
    if (!r) { search(cur.order['指図NO']); return ''; }
    cur.status = { state: '作業中', worker: staff, startAt: r.at || '', doneAt: '' };
    renderStatus();
  }
  return staff;
}


async function editDimensionOverride(i,j,reset) {
  const staff=getMe(); if(!staff) return needStaff();
  const dw=cur.drawings[i],p=dw.points[j],field=document.querySelector(`[data-dim-value="${i}:${j}"]`);
  const value=reset?'':String(field && field.value || '').normalize('NFKC').trim();
  if(!reset && (!/^\d+(?:\.\d{1,2})?$/.test(value)||Number(value)<=0||Number(value)>99999)) return alert('0より大きい数値を入力してください');
  try {const r=await run('saveDimensionOverride',cur.order['指図NO'],dw.no,p.no,value,p.baseWrite,p.fingerprint,staff);p.write=r.value;p.overridden=r.manual;p.overrideStale=false;p.confirmed=false;p.by='';p.at='';renderPoints(i);renderBoxes(i);updatePtProg();toast(reset?'自動計算値に戻しました':'手入力値を保存しました。元の計算値も確認してください');}
  catch(e){alert('寸法を保存できませんでした：'+e.message);}
}

async function editManualDimension(i, j) {
  const staff = getMe(); if (!staff) return needStaff();
  const dw = cur.drawings[i], p = dw.points[j];
  const field = document.querySelector(`[data-manual-value="${i}:${j}"]`);
  if (!field) return;
  const v = String(field.value || '').normalize('NFKC').trim();
  if (!/^\d+(?:\.\d{1,2})?$/.test(v) || Number(v) <= 0 || Number(v) > 99999) return alert('0より大きい数値を入力してください');
  try {
    const res = await run('saveManualDimension', cur.order['指図NO'], dw.no, p.manualKey, v, staff);
    dw.points.filter(q => q.manualKey === p.manualKey).forEach(q => { if (q.write !== res.value) { q.confirmed = false; q.by = ''; q.at = ''; } q.write = res.value; });
    renderPoints(i); renderBoxes(i); updatePtProg(); toast(p.manualKey + '端寸法を保存しました');
  } catch(e) { alert('寸法を保存できませんでした：' + e.message); }
}

async function togglePoint(i, j) {
  const point = cur.drawings[i].points[j];
  if (point.manualKey && !point.write && !point.confirmed) { const detail=$('#pointDetails-'+i); if(detail) detail.open=true; return alert('図面の下の「確認ポイント・寸法入力」で' + point.manualKey + '端寸法を入力してください'); }
  const staff = await ensureStarted();
  if (!staff) return;
  const dw = cur.drawings[i], p = dw.points[j];
  const next = !p.confirmed;
  p.confirmed = next; p.by = staff;
  renderPoints(i); renderBoxes(i); updatePtProg();
  try {
    const r = await run('savePointConfirm', cur.order['指図NO'], dw.no, p.no, next, staff);
    p.at = r.at; renderPoints(i);
  } catch (e) {
    p.confirmed = !next; renderPoints(i); renderBoxes(i); updatePtProg();
    alert('保存に失敗しました：' + e.message);
  }
}

/* ---------- 図面への書き込み（指・タッチペンで手書き） ---------- */
const INK_COLORS = [['#d0021b', '赤'], ['#1f6feb', '青'], ['#111111', '黒'], ['#70d03066', '緑の蛍光']];

function toggleInk(i) {
  if (inkMode && inkMode.i === i) {
    inkMode = null;
  } else {
    if (!needStaff()) return;
    if (!$('#ink-' + i)) return alert('図面が表示されてから押してください');
    setTarget = null;
    inkMode = { i, tool: 'pen', color: '#d0021b', width: 0.18 };
    toast('書き込みモード：1本指で書く／2本指でつまむと拡大・ずらすと移動');
  }
  cur.drawings.forEach((_, k) => { renderInkBar(k); renderInk(k); });
  updateStepper();
}

function renderInkBar(i) {
  const bar = $('#ib-' + i), vw = $('#vw-' + i), btn = document.querySelector(`[data-inkbtn="${i}"]`);
  if (!bar) return;
  const on = !!(inkMode && inkMode.i === i);
  bar.hidden = !on;
  if (vw) vw.classList.toggle('inking', on);
  if (btn) btn.classList.toggle('admin-on', on);
  if (!on) { bar.innerHTML = ''; return; }
  const m = inkMode;
  bar.innerHTML = `
    <button data-inktool="pen" class="${m.tool === 'pen' ? 'on' : ''}">ペン</button>
    <button data-inktool="ellipse" class="${m.tool === 'ellipse' ? 'on' : ''}" aria-label="丸">◯ 丸</button>
    <button data-inktool="rect" class="${m.tool === 'rect' ? 'on' : ''}" aria-label="四角">□ 四角</button>
    <button data-inktool="text" class="${m.tool === 'text' ? 'on' : ''}">文字</button>
    <button data-inktool="eraser" class="${m.tool === 'eraser' ? 'on' : ''}">消しゴム</button>
    <span class="sep"></span>
    ${INK_COLORS.map(([c, n]) => `<button class="col ${m.color === c ? 'on' : ''}" data-inkcolor="${c}" style="color:${c}" title="${n}">●</button>`).join('')}
    <button data-inkwidth="0.18" class="${m.width < 0.3 ? 'on' : ''}">細</button>
    <button data-inkwidth="0.4" class="${m.width >= 0.3 && m.width < 1 ? 'on' : ''}">太</button>
    <button data-inkwidth="1.2" class="${m.width >= 1 ? 'on' : ''}">蛍光幅</button>
    <span class="sep"></span>
    <button data-inkact="undo">元に戻す</button>
    <button data-inkact="clear">全部消す</button>
    <button data-inkact="done" class="done">完了</button>`;
}

// 丸・四角のパス（x・幅は横の%、y・高さは縦の%。A＝縦横比）
function shapePath(t, x, y, w, h, A) {
  const Y = y * A / 100, H = h * A / 100;
  if (t === 'rect') return `M${x} ${Y.toFixed(2)}H${(x + w).toFixed(2)}V${(Y + H).toFixed(2)}H${x}Z`;
  const rx = w / 2, ry = H / 2, cx = x + rx, cy = Y + ry;
  return `M${(cx - rx).toFixed(2)} ${cy.toFixed(2)}a${rx.toFixed(2)} ${ry.toFixed(2)} 0 1 0 ${(2 * rx).toFixed(2)} 0a${rx.toFixed(2)} ${ry.toFixed(2)} 0 1 0 ${(-2 * rx).toFixed(2)} 0Z`;
}

function inkSvg(k, A) {
  const d = k.d;
  if (d.t === 'rect' || d.t === 'ellipse') {
    const path = shapePath(d.t, d.x, d.y, d.wd, d.ht, A);
    return `<path d="${path}" stroke="${d.c}" stroke-width="${d.w}" fill="none" stroke-linejoin="round"/>
      <path class="hit" data-inkid="${esc(k.id)}" d="${path}" stroke-width="${Math.max(d.w * 6, 1.5)}"/>`;
  }
  if (d.t === 'pen') {
    const path = d.p.map((q, n) => (n ? 'L' : 'M') + q[0] + ' ' + (q[1] * A / 100).toFixed(2)).join(' ');
    return `<path d="${path}" stroke="${d.c}" stroke-width="${d.w}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
      <path class="hit" data-inkid="${esc(k.id)}" d="${path}" stroke-width="${Math.max(d.w * 6, 1.5)}"/>`;
  }
  if (d.t === 'text') {
    return `<text class="itxt" data-inkid="${esc(k.id)}" x="${d.x}" y="${(d.y * A / 100).toFixed(2)}" fill="${d.c}"
      font-size="${(d.s * A / 100).toFixed(2)}" paint-order="stroke" stroke="#fff" stroke-width="${(d.s * A / 100 / 8).toFixed(2)}">${esc(d.text)}</text>`;
  }
  return '';
}

function renderInk(i) {
  const svg = $('#ink-' + i);
  if (!svg) return;
  const v = views[i];
  svg.innerHTML = v.ink.filter(k => k.page === v.page).map(k => inkSvg(k, v.aspect)).join('') +
    `<path id="inktmp-${i}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;
  const on = !!(inkMode && inkMode.i === i);
  svg.classList.toggle('active', on);
  svg.classList.toggle('erase', on && inkMode.tool === 'eraser');
}

function attachInk(i) {
  const svg = $('#ink-' + i);
  let pts = null;      // ペンの点
  let shape = null;    // 丸・四角を描いている途中 {t, a:[x,y], b:[x,y]}
  // 2本指で拡大を始めたら、書きかけの線・図形は保存せずに消す
  views[i].cancelInk = () => {
    pts = null; shape = null;
    const el = $('#inktmp-' + i);
    if (el) el.setAttribute('d', '');
  };
  const box = (a, b) => ({ x: Math.min(a[0], b[0]), y: Math.min(a[1], b[1]), wd: Math.abs(a[0] - b[0]), ht: Math.abs(a[1] - b[1]) });
  const tmpShape = () => {
    const el = $('#inktmp-' + i), A = views[i].aspect;
    if (!el || !shape) return;
    const r = box(shape.a, shape.b);
    el.setAttribute('d', shapePath(shape.t, r.x, r.y, r.wd, r.ht, A));
    el.setAttribute('stroke', inkMode.color);
    el.setAttribute('stroke-width', inkMode.width);
  };
  const pos = e => {
    const r = svg.getBoundingClientRect();
    const f = n => Math.round(n * 100) / 100;
    return [f(Math.max(0, Math.min(100, (e.clientX - r.left) / r.width * 100))), f(Math.max(0, Math.min(100, (e.clientY - r.top) / r.height * 100)))];
  };
  const tmp = () => {
    const el = $('#inktmp-' + i), A = views[i].aspect;
    if (!el || !pts) return;
    el.setAttribute('d', pts.map((q, n) => (n ? 'L' : 'M') + q[0] + ' ' + q[1] * A / 100).join(' '));
    el.setAttribute('stroke', inkMode.color);
    el.setAttribute('stroke-width', inkMode.width);
  };
  svg.addEventListener('pointerdown', e => {
    if (!inkMode || inkMode.i !== i) return;
    e.preventDefault();
    if (views[i].pinch || (e.pointerType === 'touch' && !e.isPrimary)) return;   // 2本目の指は書かない（拡大の操作）
    if (inkMode.tool === 'pen') {
      pts = [pos(e)];
      svg.setPointerCapture(e.pointerId);
      tmp();
    } else if (inkMode.tool === 'rect' || inkMode.tool === 'ellipse') {
      const p = pos(e);
      shape = { t: inkMode.tool, a: p, b: p };
      svg.setPointerCapture(e.pointerId);
      tmpShape();
    } else if (inkMode.tool === 'text') {
      const p = pos(e);
      const text = prompt('図面に書く文字を入力してください');
      if (text && text.trim()) saveInk(i, { t: 'text', c: inkMode.color, s: inkMode.width >= 0.3 ? 3.4 : 2.3, x: p[0], y: p[1], text: text.trim() });
    } else if (inkMode.tool === 'eraser') {
      const el = e.target.closest('[data-inkid]');
      if (el) eraseInk(i, [el.dataset.inkid]);
    }
  });
  svg.addEventListener('pointermove', e => {
    if (views[i].pinch) return;
    if (shape) { shape.b = pos(e); return tmpShape(); }
    if (!pts) return;
    const p = pos(e), last = pts[pts.length - 1];
    if (Math.hypot(p[0] - last[0], p[1] - last[1]) > 0.12) { pts.push(p); tmp(); }   // 細かすぎる点は省いて軽くする
  });
  const end = () => {
    if (shape) {
      const r = box(shape.a, shape.b), t = shape.t;
      shape = null;
      const el = $('#inktmp-' + i);
      if (el) el.setAttribute('d', '');
      if (r.wd < 0.6 || r.ht < 0.6) return toast('もう少し大きく、斜めになぞってください');
      return saveInk(i, Object.assign({ t, c: inkMode.color, w: inkMode.width }, r));
    }
    if (!pts) return;
    const p = pts;
    pts = null;
    const el = $('#inktmp-' + i);
    if (el) el.setAttribute('d', '');
    if (p.length === 1) p.push([p[0][0] + 0.05, p[0][1]]);   // 点を打っただけでも見えるように
    saveInk(i, { t: 'pen', c: inkMode.color, w: inkMode.width, p: p });
  };
  svg.addEventListener('pointerup', end);
  svg.addEventListener('pointercancel', end);
}

async function saveInk(i, d) {
  const staff = getMe();
  if (!staff) return needStaff();
  const v = views[i], dw = cur.drawings[i];
  const item = { id: 'tmp' + Date.now(), page: v.page, by: staff, d };
  v.ink.push(item);
  renderInk(i);
  try {
    const r = await run('addInk', cur.order['指図NO'], dw.inkKey, v.page, JSON.stringify(d), staff);
    item.id = r.id;
    inkUndo.push({ i, id: r.id });
    renderInk(i);
  } catch (e) {
    v.ink = v.ink.filter(k => k !== item);
    renderInk(i);
    alert('書き込みを保存できませんでした：' + e.message);
  }
}

async function eraseInk(i, ids) {
  const v = views[i], dw = cur.drawings[i];
  const back = v.ink.slice();
  v.ink = v.ink.filter(k => ids.indexOf(k.id) < 0);
  renderInk(i);
  try {
    await run('deleteInk', cur.order['指図NO'], dw.inkKey, v.page, ids);
  } catch (e) {
    v.ink = back; renderInk(i);
    alert('消せませんでした：' + e.message);
  }
}

async function inkAction(i, act) {
  const v = views[i], dw = cur.drawings[i];
  if (act === 'done') return toggleInk(i);
  if (act === 'undo') {
    const last = [...inkUndo].reverse().find(u => u.i === i && v.ink.some(k => k.id === u.id));
    if (!last) return toast('この画面で書いたものはありません');
    inkUndo = inkUndo.filter(u => u !== last);
    return eraseInk(i, [last.id]);
  }
  if (act === 'clear') {
    const n = v.ink.filter(k => k.page === v.page).length;
    if (!n) return toast('書き込みはありません');
    if (!confirm(`このページの書き込み ${n} 件を全部消しますか？（他の人の書き込みも消えます）`)) return;
    v.ink = v.ink.filter(k => k.page !== v.page);
    renderInk(i);
    try { await run('deleteInk', cur.order['指図NO'], dw.inkKey, v.page, []); }
    catch (e) { alert('消せませんでした：' + e.message); search(cur.order['指図NO']); }
  }
}

/* ---------- 原本（指示書・パラメータ表）の表示 ---------- */
// 回転の向き（0/90/180/270）。指示書は縦の用紙が横向きでスキャンされるので、最初は90°回して表示
const DOC_ROT_DEFAULT = { shiji: 90, param: 0 };
function docRot(kind) {
  const v = store('docRot_' + kind);
  return v === '' ? DOC_ROT_DEFAULT[kind] || 0 : Number(v) || 0;
}
function rotateCanvas(cv, deg) {
  if (!deg) return cv;
  const out = document.createElement('canvas');
  const sw = deg % 180 !== 0;
  out.width = sw ? cv.height : cv.width; out.height = sw ? cv.width : cv.height;
  const g = out.getContext('2d');
  g.translate(out.width / 2, out.height / 2);
  g.rotate(deg * Math.PI / 180);
  g.drawImage(cv, -cv.width / 2, -cv.height / 2);
  return out;
}
const docPages = {};   // URL → 描いたページ（回転し直し用）

// 原本（PDF・画像）を読み込んで、ページごとのキャンバスにする（読み込み済みならそれを使う）
async function getDocPages(url) {
  if (docPages[url]) return docPages[url];
  let f = fileCache[url];
  if (!f) f = fileCache[url] = await run('getDrawingFile', url);
  const bytes = base64ToBytes(f.data);
  const pages = [];
  if (/pdf/i.test(f.mime) && window.pdfjsLib) {
    const doc = await pdfjsLib.getDocument({ data: bytes }).promise;
    for (let p = 1; p <= doc.numPages; p++) {
      const page = await doc.getPage(p);
      const v1 = page.getViewport({ scale: 1 });
      const vp = page.getViewport({ scale: 2400 / Math.max(v1.width, v1.height) });   // 部品表を拡大しても読めるように
      const cv = document.createElement('canvas');
      cv.width = Math.round(vp.width); cv.height = Math.round(vp.height);
      await page.render({ canvasContext: cv.getContext('2d'), viewport: vp }).promise;
      pages.push(cv);
    }
  } else {
    const img = await loadImage(new Blob([bytes], { type: f.mime }));
    const cv = document.createElement('canvas');
    cv.width = img.naturalWidth; cv.height = img.naturalHeight;
    cv.getContext('2d').drawImage(img, 0, 0);
    pages.push(cv);
  }
  return (docPages[url] = pages);
}

async function loadDocs(seq) {
  for (const box of document.querySelectorAll('.docv[data-doc]')) {
    const url = box.dataset.doc;
    try {
      await getDocPages(url);
      if (seq !== renderSeq) return;
      showDoc(box);
    } catch (e) {
      box.innerHTML = `<p class="note">原本を表示できませんでした（${esc(e.message)}）</p>`;
    }
  }
}

function showDoc(box) {
  const pages = docPages[box.dataset.doc];
  if (!pages) return;
  const kind = box.dataset.kind, rot = docRot(kind);
  box.innerHTML = pages.map((cv, k) => {
    // 横長のページだけ回す（縦にスキャンされたページはそのまま）
    const r = cv.width > cv.height ? rot : (rot % 180 === 0 ? rot : 0);
    return `<img src="${rotateCanvas(cv, r).toDataURL('image/jpeg', 0.85)}" alt="原本 ${k + 1}ページ">`;
  }).join('');
}

function turnDoc(kind) {
  store('docRot_' + kind, String((docRot(kind) + 90) % 360));
  document.querySelectorAll(`.docv[data-kind="${kind}"]`).forEach(showDoc);
}

