// 原本の部品表を切り出して拡大表示（部品データが無いときもこれで見られる）
async function renderPartsDoc() {
  const body = $('#pvBody');
  const url = cur.order['指示書PDF'];
  if (!url) {
    body.innerHTML = `<div class="pv-empty"><b>部品リストがありません</b>
      <p>事務の画面で、この指示書の原本（スキャン）か、部品のCSVを登録すると表示できます。</p></div>`;
    return;
  }
  body.innerHTML = '<p class="note" style="padding:20px">原本を読み込み中…</p>';
  try {
    const pages = await getDocPages(url);
    const rot = docRot('shiji');
    const imgs = pages.map(cv => {
      const up = rotateCanvas(cv, cv.width > cv.height ? rot : (rot % 180 === 0 ? rot : 0));
      const a = PARTS_AREA;
      const sx = Math.round(up.width * a.x), sy = Math.round(up.height * a.y), sw = Math.round(up.width * a.w);
      const sh = partsBottom(up, sx, sy, sw, Math.round(up.height * a.h)) ;
      if (sh < up.height * 0.05) return '';   // 部品の行が無いページは出さない
      const out = document.createElement('canvas');
      out.width = sw; out.height = sh;
      out.getContext('2d').drawImage(up, sx, sy, sw, sh, 0, 0, sw, sh);
      return out.toDataURL('image/jpeg', 0.9);
    }).filter(Boolean);
    body.innerHTML = `<p class="note pv-foot">指示書の原本から、部品表の部分を切り出しています（${imgs.length}ページ）。</p>` +
      imgs.map((src, k) => `<img class="pv-img" src="${src}" alt="部品表 ${k + 1}">`).join('');
  } catch (e) {
    body.innerHTML = `<p class="note" style="padding:20px">原本を表示できませんでした（${esc(e.message)}）</p>`;
  }
}

// 空の行が続くページは、最後に文字がある行の少し下で切る
function partsBottom(cv, sx, sy, sw, sh) {
  const g = cv.getContext('2d', { willReadFrequently: true });
  // 棚番の列の内側（左から3〜15%）だけを見る。罫線（数px）ではなく、文字（ある程度の高さが続く濃い部分）を探す
  const bx = sx + Math.round(sw * 0.03), bw = Math.round(sw * 0.12);
  const textH = Math.max(6, Math.round(cv.height * 0.004));   // 文字の高さの目安（罫線より十分高い）
  const data = g.getImageData(bx, sy, bw, sh).data;
  let run = 0, last = 0;
  for (let y = 0; y < sh; y++) {
    let dark = 0;
    for (let x = 0; x < bw; x++) { const k = (y * bw + x) * 4; if (data[k] < 120) dark++; }
    const has = dark > bw * 0.04 && dark < bw * 0.7;
    run = has ? run + 1 : 0;
    if (run >= textH) last = y;
  }
  return Math.min(sh, last + Math.round(cv.height * 0.025));
}

