const offProg = t => { $('#offProg').textContent = t; };


/* ===================== パラメータ表（PDF）から数値を読み取る =====================
 * スキャンしたパラメータ表は「1列＝1項目」の表。罫線から列を見つけ、列ごとに
 *   見出し（上の番号＋項目名）と、値のマスを切り出して1枚の画像に縦に並べ、
 *   Googleの文字認識で読む（「列07見出し」「列07値」の目印で、どの列の文字か分かる）
 * 読み取った値は必ず原本の切り抜きと並べて見せ、人が確認してから登録する
 */
const PR_CHUNK = 13;   // 1枚の画像に並べる列の数

// 黒い点の地図（1＝黒）
function inkMap(cv) {
  const W = cv.width, H = cv.height;
  const d = cv.getContext('2d').getImageData(0, 0, W, H).data;
  const a = new Uint8Array(W * H);
  for (let i = 0, j = 0; i < a.length; i++, j += 4) a[i] = (d[j] * 0.3 + d[j + 1] * 0.59 + d[j + 2] * 0.11) < 150 ? 1 : 0;
  return { a, W, H };
}
function runGroups(list, gap) {
  const g = [];
  list.forEach(i => { const l = g[g.length - 1]; if (l && i - l[1] <= gap) l[1] = i; else g.push([i, i]); });
  return g;
}

// パラメータ表の罫線を探す。見つからなければ null（図面など）
function findParamGrid(cv) {
  const { a, W, H } = inkMap(cv);
  const dark = (x, y) => a[y * W + x];
  // 横線：その行（上下1点も含む）の黒の割合が高く、すぐ上下より飛び抜けて高い行
  const frac = new Float32Array(H);
  for (let y = 1; y < H - 1; y++) {
    let n = 0;
    for (let x = 0, o = y * W; x < W; x++) if (a[o + x] | a[o - W + x] | a[o + W + x]) n++;
    frac[y] = n / W;
  }
  const lim = Math.floor(H * 0.6), cand = [];
  for (let y = 12; y < lim; y++) {
    if (frac[y] > 0.2 && frac[y] - Math.max(frac[y - 10], frac[y + 10]) > 0.12) cand.push(y);
  }
  const lines = runGroups(cand, 4).map(g => (g[0] + g[1]) >> 1);
  if (!lines.length) return null;
  // 表の左右：一番上の線の、いちばん長いつながり（傾き分として上下8点まで見る）
  const anyCol = (y, x) => { for (let k = -8; k <= 8; k++) { const yy = y + k; if (yy >= 0 && yy < H && dark(x, yy)) return 1; } return 0; };
  const xs = [];
  for (let x = 0; x < W; x++) if (anyCol(lines[0], x)) xs.push(x);
  const seg = runGroups(xs, 40).sort((p, q) => (q[1] - q[0]) - (p[1] - p[0]))[0];
  if (!seg || seg[1] - seg[0] < W * 0.6) return null;
  const [x0, x1] = seg;
  const tab = lines.filter(y => { let n = 0; for (let x = x0; x <= x1; x++) n += anyCol(y, x); return n / (x1 - x0 + 1) > 0.9; });
  if (tab.length < 3) return null;
  // 縦線：見出しの帯で、上から下まで黒が続く列（傾き分として左右3点まで見る）
  const ya = tab[0] + 6, yb = tab[1] - 6, hh = yb - ya;
  if (hh < 20) return null;
  const vf = new Float32Array(W);
  for (let y = ya; y < yb; y++) {
    const o = y * W;
    let last = -99;
    const hit = new Uint8Array(W);
    for (let x = 0; x < W; x++) { if (a[o + x]) last = x; if (x - last <= 3) hit[x] = 1; }
    last = 1e9;
    for (let x = W - 1; x >= 0; x--) { if (a[o + x]) last = x; if (last - x <= 3) hit[x] = 1; }
    for (let x = 0; x < W; x++) vf[x] += hit[x];
  }
  const vx = [];
  for (let x = Math.max(0, x0 - 5); x < W - 3; x++) if (vf[x] / hh > 0.8) vx.push(x);
  const cols = runGroups(vx, 8).map(g => (g[0] + g[1]) >> 1);
  if (cols.length < 21) return null;   // パラメータ表は列が多い（30列以上）
  const rows = [];
  for (let k = 1; k < tab.length - 1; k++) if (tab[k + 1] - tab[k] > 30) rows.push([tab[k], tab[k + 1]]);
  if (!rows.length) return null;
  return { tab, cols, rows: rows.slice(0, 6) };
}

// 仕分け用：パラメータ表のページか（大きな画像は縮めてから調べる）
function isParamSheet(cv) {
  if (cv.width <= 3600 && cv.height <= 3600) return !!findParamGrid(cv);
  const sc = 3400 / Math.max(cv.width, cv.height);
  const c = document.createElement('canvas');
  c.width = Math.round(cv.width * sc); c.height = Math.round(cv.height * sc);
  c.getContext('2d').drawImage(cv, 0, 0, c.width, c.height);
  return !!findParamGrid(c);
}

// 切り出して、黒い部分だけに詰める（何も無ければ null）
function cropInk(cv, x, y, w, h, pad) {
  if (w < 4 || h < 4) return null;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  c.getContext('2d').drawImage(cv, x, y, w, h, 0, 0, w, h);
  const { a } = inkMap(c);
  let l = w, r = -1, t = h, b = -1;
  for (let yy = 0; yy < h; yy++) for (let xx = 0; xx < w; xx++) if (a[yy * w + xx]) {
    if (xx < l) l = xx; if (xx > r) r = xx; if (yy < t) t = yy; if (yy > b) b = yy;
  }
  if (r < 0 || (r - l) * (b - t) < 12) return null;
  l = Math.max(0, l - pad); t = Math.max(0, t - pad); r = Math.min(w - 1, r + pad); b = Math.min(h - 1, b + pad);
  const o = document.createElement('canvas');
  o.width = r - l + 1; o.height = b - t + 1;
  const g = o.getContext('2d');
  g.fillStyle = '#fff'; g.fillRect(0, 0, o.width, o.height);
  g.drawImage(c, l, t, o.width, o.height, 0, 0, o.width, o.height);
  return o;
}

// 列ごとに切り出して、文字認識に送る画像（PNG・base64）を作る
function buildParamComposites(cv, grid) {
  const S = 2, cells = [];
  const [t0, t1] = grid.tab;
  for (let c = 0; c < grid.cols.length - 1; c++) {
    const xa = grid.cols[c] + 4, w = grid.cols[c + 1] - 4 - xa;
    const num = cropInk(cv, xa, Math.max(0, t0 - 46), w, 40, 3);   // 表の上の番号
    const head = cropInk(cv, xa, t0 + 6, w, t1 - t0 - 11, 3);
    const vals = grid.rows.map(([r0, r1]) => cropInk(cv, xa, r0 + 6, w, r1 - r0 - 11, 4));
    cells.push({ c, num, head, vals });
  }
  const out = [];
  for (let k = 0; k < cells.length; k += PR_CHUNK) {
    const part = cells.slice(k, k + PR_CHUNK);
    const items = [];
    part.forEach(x => {
      items.push({ label: `列${String(x.c).padStart(2, '0')}見出し`, imgs: [x.num, x.head] });
      x.vals.forEach((v, r) => items.push({ label: `列${String(x.c).padStart(2, '0')}値${r + 1}`, imgs: [v] }));
    });
    const lh = 52;
    let Wc = 460, Hc = 20;
    items.forEach(it => { Hc += lh; it.imgs.forEach(im => { if (im) { Wc = Math.max(Wc, im.width * S + 40); Hc += im.height * S + 10; } }); Hc += 24; });
    const o = document.createElement('canvas');
    o.width = Wc; o.height = Hc;
    const g = o.getContext('2d');
    g.fillStyle = '#fff'; g.fillRect(0, 0, Wc, Hc);
    g.fillStyle = '#000'; g.font = 'bold 34px sans-serif'; g.textBaseline = 'top';
    let y = 10;
    items.forEach(it => {
      g.fillText(it.label, 10, y); y += lh;
      it.imgs.forEach(im => { if (im) { g.drawImage(im, 20, y, im.width * S, im.height * S); y += im.height * S + 10; } });
      y += 24;
    });
    out.push(o.toDataURL('image/png').split(',')[1]);
  }
  return { images: out, cells };
}

// 文字認識の結果を、列ごとの「見出し」「値」に分ける
function parseParamOcr(texts) {
  const t = texts.join('\n').normalize('NFKC').replace(/\r/g, '');
  const re = /列\s*(\d{1,2})\s*(見\s*出\s*し|値\s*(\d)?)/g;
  const marks = [];
  let m;
  while ((m = re.exec(t))) marks.push({ c: Number(m[1]), kind: /値/.test(m[2]) ? 'val' : 'head', r: Number(m[3] || 1) - 1, s: m.index, e: re.lastIndex });
  const cols = {};
  marks.forEach((k, i) => {
    const body = t.slice(k.e, i + 1 < marks.length ? marks[i + 1].s : t.length).trim();
    const col = cols[k.c] = cols[k.c] || { head: '', vals: [] };
    if (k.kind === 'head') col.head = body; else col.vals[k.r] = body;
  });
  return cols;
}

// 小便器（U）のパラメータ表の項目名（見出しの読み違いで名前が崩れないように）。他のユニットは表の見出しを使う
const PR_NAMES_U = { 1: 'シリーズ', 2: 'ユニット種類', 3: '器具', 4: '金具', 5: 'アクセサリー', 6: '連数', 7: '分割パターン', 8: '左端寸法',
  9: '器具ピッチ寸法', 10: '右端寸法', 11: '通気管抜き方向', 12: '給水管抜き方向', 13: '排水管抜き方向', 14: '幅木脱臭管抜き方向',
  15: '陶器色', 16: '甲板種類・色', 17: '分割処理', 18: '前面板色', 19: '壁固定仕様', 20: '壁固定補強', 21: '床固定仕様', 22: '床段差',
  23: '奥行き（前面板までの前出）', 24: 'テスリ有／無、固定位置', 25: 'テスリ種類', 26: 'テスリ色', 27: '前面板フック設置有／無',
  28: 'フック種類', 29: '前面板側面仕上げ有／無', 30: 'IoT仕様', 31: '受注形態', 32: '配管図有／無' };

// 列の番号を決める：読めた番号の「列の位置との差」で一番多いものを使う（番号の読み違いに強い）
function paramItemsFrom(cols, cells, rowIdx) {
  const diffs = {};
  Object.keys(cols).forEach(c => {
    const m = String(cols[c].head).match(/^\s*(\d{1,2})(?!\d)/);
    if (m) { const d = Number(m[1]) - Number(c); diffs[d] = (diffs[d] || 0) + 1; }
  });
  const best = Object.keys(diffs).sort((x, y) => diffs[y] - diffs[x])[0];
  const off = best === undefined ? null : Number(best);
  const defs = paramDefs || [];
  const clean = v => String(v || '').replace(/\s+/g, '').replace(/[|｜]/g, '');
  const items = [];
  const c2 = off === null ? null : cols[2 - off];
  const isU = !!c2 && /^U$/i.test(clean(c2.vals[rowIdx]).replace(/^.*:/, ''));
  const PR_NAMES = isU ? PR_NAMES_U : {};
  cells.forEach(cell => {
    const col = cols[cell.c] || { head: '', vals: [] };
    const no = off === null ? null : cell.c + off;
    if (no === null || no < 1 || no > 60) return;
    const ocrName = clean(String(col.head).replace(/^\s*\d{1,2}/, ''));
    const def = defs.find(d => String(d.no) === String(no));
    items.push({
      no, name: (def && def.name) || PR_NAMES[no] || ocrName || ('項目' + no), ocrName,
      value: clean(col.vals[rowIdx]), read: clean(col.vals[rowIdx]),
      img: cell.vals[rowIdx] ? cell.vals[rowIdx].toDataURL('image/png') : '',
      req: !!(def && def.required),
    });
  });
  const floor = cols[0] ? clean(cols[0].vals[rowIdx]) : '';
  return { items, floor, ok: off !== null };
}

// ページ（canvas）から読み取って、確認画面を開く
let prState = null;
async function readParamSheet(cv, key, keyType, src) {
  const grid = findParamGrid(cv);
  if (!grid) {
    alert('パラメータ表の表（罫線）が見つかりませんでした。\n・パラメータ表のページか確認してください\n・まっすぐ、200dpi以上でスキャンしてください');
    return;
  }
  $('#loading').textContent = '文字を読み取り中…（20〜40秒かかります）';
  loading(true);
  try {
    const { images, cells } = buildParamComposites(cv, grid);
    // 画像を2つずつ並行して読む（待ち時間を短く）
    const texts = [];
    for (let k = 0; k < images.length; k += 2) texts.push(...await run('ocrImages', officePin, images.slice(k, k + 2)));
    const cols = parseParamOcr(texts);
    const rows = grid.rows.map((_, r) => paramItemsFrom(cols, cells, r));
    if (!rows[0].ok || !rows[0].items.length) throw new Error('項目の番号を読み取れませんでした');
    prState = { rows, row: 0, key: key || '', keyType: keyType || '指図NO', src };
    openParamReview();
  } catch (err) {
    alert('読み取りに失敗しました：' + err.message + '\n（Excel・CSVがあれば、そちらで取り込むのが確実です）');
  } finally {
    loading(false);
    $('#loading').textContent = '読み込み中…';
  }
}

function openParamReview() {
  const st = prState, cur0 = st.rows[st.row];
  $('#prSub').textContent = st.src || '';
  const filled = cur0.items.filter(x => x.value).length;
  $('#prBody').innerHTML = `<div class="pr-wrap">
    <p class="note">左の「原本」と見比べて、違う値は直してください。手書きの書き込み（丸・寸法のメモ）は読み取りません。<br>
      読み取れた項目：${filled} / ${cur0.items.length}　<b style="color:var(--pen)">赤い欄</b>は空欄、<b style="color:var(--skin-ink)">肌色の欄</b>は直した値です。</p>
    ${st.rows.length > 1 ? `<div class="pr-row">${st.rows.map((r, k) => `<button class="btn sm ${k === st.row ? 'primary' : ''}" data-prrow="${k}">${k + 1}行目 ${esc(r.floor)}</button>`).join('')}</div>` : ''}
    <div class="pr-key"><b>登録先</b>
      <select id="prKeyType">${['指図NO', '組立品番'].map(k => `<option ${k === st.keyType ? 'selected' : ''}>${k}</option>`).join('')}</select>
      <input id="prKey" value="${esc(st.key)}" placeholder="指図NOか組立品番" autocomplete="off">
      ${cur0.floor ? `<span class="note">表の適用階：${esc(cur0.floor)}</span>` : ''}</div>
    <table class="pr-tbl"><thead><tr><th>No</th><th>項目</th><th>原本</th><th>読み取った値（直せます）</th></tr></thead><tbody>
      ${cur0.items.map((x, k) => `<tr class="${x.req ? 'req' : ''} ${x.value ? '' : 'empty'} ${x.value !== x.read ? 'edited' : ''}">
        <td class="no">${x.no}</td>
        <td class="nm">${esc(x.name)}${x.ocrName && x.ocrName !== x.name ? `<small>表の見出し：${esc(x.ocrName)}</small>` : ''}</td>
        <td>${x.img ? `<img src="${x.img}" alt="原本の${esc(x.name)}">` : '<span class="note">空欄</span>'}</td>
        <td><input data-pritem="${k}" value="${esc(x.value)}" autocomplete="off"></td></tr>`).join('')}
    </tbody></table>
    <div class="pr-foot"><button class="btn primary big" id="prSave">確認した内容で登録する</button></div>
  </div>`;
  $('#prView').hidden = false;
  document.body.style.overflow = 'hidden';
}
function closeParamReview() {
  $('#prView').hidden = true;
  document.body.style.overflow = '';
}

async function saveParamReview() {
  const st = prState, row = st.rows[st.row];
  const staff = needStaff();
  if (!staff) return;
  st.key = $('#prKey').value.trim(); st.keyType = $('#prKeyType').value;
  if (!st.key) { alert('登録先の' + st.keyType + 'を入力してください'); return $('#prKey').focus(); }
  const items = row.items.filter(x => x.value);
  const miss = row.items.filter(x => x.req && !x.value);
  if (miss.length && !confirm(`必須の項目が空欄です：${miss.map(x => x.no + ' ' + x.name).join('、')}\nこのまま登録しますか？`)) return;
  if (!confirm(`${st.keyType} ${st.key} に、パラメータ ${items.length} 項目を登録します。\n原本と見比べて確認しましたか？（同じ${st.keyType}の古いパラメータは置き換わります）`)) return;
  loading(true);
  try {
    const table = [[st.keyType, ...items.map(x => `${x.no} ${x.name}`)], [st.key, ...items.map(x => x.value)]];
    const msg = await run('importParamRows', officePin, table, staff, 'pdf');
    if (st.onDone) st.onDone();
    closeParamReview();
    toast('パラメータを登録しました');
    $('#offParamMsg').textContent = msg;
    loadOfficeStatus();
  } catch (e) {
    alert('登録できませんでした：' + e.message);
  } finally { loading(false); }
}

function onParamReviewEvent(e) {
  const inp = e.target.closest('[data-pritem]');
  if (inp && e.type === 'input') {
    const x = prState.rows[prState.row].items[Number(inp.dataset.pritem)];
    x.value = inp.value.trim();
    const tr = inp.closest('tr');
    tr.classList.toggle('empty', !x.value); tr.classList.toggle('edited', x.value !== x.read);
    return;
  }
  if (e.type !== 'click') return;
  const r = e.target.closest('[data-prrow]');
  if (r) { prState.key = $('#prKey').value; prState.keyType = $('#prKeyType').value; prState.row = Number(r.dataset.prrow); return openParamReview(); }
  if (e.target.closest('#prSave')) return saveParamReview();
}

// PDF（またはスキャン画像）を、表を読める解像度の canvas にする
async function pageCanvasFromPdf(doc, p) {
  const page = await doc.getPage(p);
  const vp = page.getViewport({ scale: 200 / 72 });
  const cv = document.createElement('canvas');
  cv.width = Math.round(vp.width); cv.height = Math.round(vp.height);
  await page.render({ canvasContext: cv.getContext('2d'), viewport: vp }).promise;
  return cv;
}
async function canvasFromImageBlob(blob) {
  const img = await loadImage(blob);
  const sc = Math.min(1, 3500 / Math.max(img.naturalWidth, img.naturalHeight));
  const cv = document.createElement('canvas');
  cv.width = Math.round(img.naturalWidth * sc); cv.height = Math.round(img.naturalHeight * sc);
  const g = cv.getContext('2d');
  g.fillStyle = '#fff'; g.fillRect(0, 0, cv.width, cv.height);
  g.drawImage(img, 0, 0, cv.width, cv.height);
  return cv;
}

// 事務：「パラメータ表のPDFから読む」
async function readParamPdfFile(e) {
  const f = e.target.files[0];
  e.target.value = '';
  if (!f || !needStaff()) return;
  loading(true);
  let cv = null;
  try {
    if (/pdf/i.test(f.type) || /\.pdf$/i.test(f.name)) {
      const doc = await pdfjsLib.getDocument({ data: new Uint8Array(await f.arrayBuffer()) }).promise;
      for (let p = 1; p <= Math.min(doc.numPages, 10) && !cv; p++) {
        const c = await pageCanvasFromPdf(doc, p);
        if (findParamGrid(c)) cv = c;
      }
    } else {
      const c = await canvasFromImageBlob(f);
      if (findParamGrid(c)) cv = c;
    }
  } catch (err) {
    loading(false);
    return alert('ファイルを開けませんでした：' + err.message);
  }
  loading(false);
  if (!cv) return alert('パラメータ表の表（罫線）が見つかりませんでした。\nまっすぐ、200dpi以上でスキャンしたPDFを選んでください。');
  await readParamSheet(cv, '', '指図NO', f.name);
}

// まとめて登録：仕分けで「パラメータ表」にしたページを読む（登録先はその指示書の指図NO）
async function readOfficeParamPage(gid) {
  if (!needStaff()) return;
  const g = groupOffice().groups.find(x => x.id === gid);
  if (!g || !g.param.length) return;
  loading(true);
  let cv = null;
  try {
    for (const k of g.param) {
      const pg = office.pages[k], f = office.files[pg.fi];
      const c = f.isPdf
        ? await pageCanvasFromPdf(f.doc = f.doc || await pdfjsLib.getDocument({ data: f.bytes.slice(0) }).promise, pg.p + 1)
        : await canvasFromImageBlob(new Blob([f.jpg], { type: 'image/jpeg' }));
      if (findParamGrid(c)) { cv = c; break; }
    }
  } catch (err) {
    loading(false);
    return alert('ページを開けませんでした：' + err.message);
  }
  loading(false);
  if (!cv) return alert('このページにパラメータ表の表（罫線）が見つかりませんでした。仕分けを確認してください。');
  const short = String(gid).replace(/^0+(?=\d)/, '');
  await readParamSheet(cv, gid, '指図NO', `指図NO ${short}${g.hin ? '（' + g.hin + '）' : ''}`);
  if (prState) prState.onDone = () => { office.paramRead = office.paramRead || {}; office.paramRead[gid] = true; renderOffice(); };
}

/* ---------- CSVの読み込み ---------- */
const isCsvFile = f => /\.csv$/i.test(f.name) || /csv/i.test(f.type);

// 文字コードを判定して読む（UTF-8 で読めなければ Shift_JIS＝Excelの日本語CSV）
async function readCsvText(file) {
  const buf = await file.arrayBuffer();
  let text;
  try { text = new TextDecoder('utf-8', { fatal: true }).decode(buf); }
  catch (e) { text = new TextDecoder('shift_jis').decode(buf); }
  return text.replace(/^﻿/, '');
}

// CSVを表にする（"" で囲んだ値・値の中のカンマや改行にも対応）
function parseCsv(text) {
  const rows = [];
  let row = [], cell = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; }
      else cell += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some(v => v.trim() !== '')) rows.push(row.map(v => v.trim()));
      row = [];
    } else cell += c;
  }
  row.push(cell);
  if (row.some(v => v.trim() !== '')) rows.push(row.map(v => v.trim()));
  return rows;
}

// 指示書の一覧の見出し（言い方の違いを吸収）
const ORDER_COLS = {
  '指図NO': ['指図NO', '指図No', '指図番号', '指図'],
  '出荷指示NO': ['出荷指示NO', '出荷指示番号', '出荷指示'],
  '組立品番': ['組立品番', '品番', '組立品目'],
  '品名': ['品名'],
  '工事NO': ['工事NO', '工事番号'],
  '工事名': ['工事名', '現場名', '物件名', '現場'],
  '組立場所': ['組立場所'],
  '出荷日': ['出荷日', '出荷予定日'],
  '組立日': ['組立日'],
  '組立開始日': ['組立開始日', '組立日(開始)', '組立日開始'],
  '組立終了日': ['組立終了日', '組立日(終了)', '組立日終了'],
  '製作台数': ['製作台数'],
  '組立台数': ['組立台数', '台数'],
  '適用階': ['適用階', '階', 'フロア'],
  'パラメータ文字列': ['パラメータ文字列', 'パラメータ'],
};
const normHead = h => String(h || '').normalize('NFKC').replace(/\s+/g, '').toUpperCase();
function orderColumns(head) {
  const map = {};
  head.forEach((h, j) => {
    const n = normHead(h);
    for (const key of Object.keys(ORDER_COLS)) {
      if (map[key] === undefined && ORDER_COLS[key].some(a => normHead(a) === n)) { map[key] = j; break; }
    }
  });
  return map;
}
// 部品リストの見出し
const PART_COLS = {
  '指図NO': ['指図NO', '指図No', '指図番号', '指図'],
  '行NO': ['行NO', '行', 'NO', '行番号'],
  '棚番': ['棚番', '棚', 'ロケーション'],
  '品番': ['品番', '部品品番', '部品番号'],
  '単位数': ['単位数', '単位'],
  '組立数': ['組立数', '取揃数', '数量', '合計', '数'],
  '同梱数': ['同梱数', '同梱'],
  '品名': ['品名', '部品名', '名称'],
};
function partColumns(head) {
  const map = {};
  head.forEach((h, j) => {
    const n = normHead(h);
    for (const key of Object.keys(PART_COLS)) {
      if (map[key] === undefined && PART_COLS[key].some(a => normHead(a) === n)) { map[key] = j; break; }
    }
  });
  return map;
}
function csvPartRows(table) {
  const cols = partColumns(table[0]);
  return table.slice(1).map(r => {
    const o = {};
    Object.keys(cols).forEach(k => { o[k] = r[cols[k]] || ''; });
    return o;
  }).filter(o => o['指図NO'] && o['品番']);
}

// 「指示書の一覧」か「パラメータ」か「部品リスト」か
function csvKind(table) {
  const head = table[0] || [];
  const pc = partColumns(head);
  if (pc['品番'] !== undefined && (pc['棚番'] !== undefined || pc['組立数'] !== undefined) && pc['指図NO'] !== undefined) return 'parts';
  const numbered = head.filter(h => /^\d+[\s._:：]*\S/.test(String(h).normalize('NFKC'))).length;
  const cols = orderColumns(head);
  if (numbered >= 3) return 'param';
  if (cols['指図NO'] !== undefined && (cols['工事名'] !== undefined || cols['出荷日'] !== undefined || cols['組立品番'] !== undefined)) return 'order';
  if (cols['組立品番'] !== undefined || cols['指図NO'] !== undefined) return 'param';
  return '';
}
// 指示書の一覧を、登録用の形にする
function csvOrderRows(table) {
  const cols = orderColumns(table[0]);
  return table.slice(1).map(r => {
    const o = {};
    Object.keys(cols).forEach(k => { o[k] = r[cols[k]] || ''; });
    if (!o['組立日'] && (o['組立開始日'] || o['組立終了日'])) o['組立日'] = [o['組立開始日'], o['組立終了日']].filter(Boolean).join('～');
    delete o['組立開始日']; delete o['組立終了日'];
    return o;
  }).filter(o => o['指図NO']);
}

// パラメータ欄：CSVを読んで、貼り付け欄に入れる
async function readParamCsv(e) {
  const f = e.target.files[0];
  e.target.value = '';
  if (!f) return;
  try {
    const table = parseCsv(await readCsvText(f));
    if (table.length < 2) return alert('CSVにデータの行がありません');
    $('#offParam').value = table.map(r => r.join('\t')).join('\n');
    $('#offParamMsg').textContent = `「${f.name}」を読みました（${table.length - 1}行）。内容を確認して「取り込む」を押してください。`;
  } catch (err) {
    alert('CSVを読めませんでした：' + err.message);
  }
}

function csvHtml() {
  if (!office.csv || !office.csv.length) return '';
  const label = { order: '指示書の一覧', param: 'パラメータ', parts: '部品リスト', '': '（種類を選んでください）' };
  return `<h4 style="margin:12px 0 6px">CSV（${office.csv.length}ファイル）</h4>
    <table class="tbl"><thead><tr><th>ファイル</th><th>種類</th><th>行数</th><th>見出し</th><th>結果</th></tr></thead><tbody>
    ${office.csv.map((c, k) => `<tr><td>${esc(c.name)}</td>
      <td><select data-csvkind="${k}">${['order', 'param', 'parts', ''].map(v => `<option value="${v}" ${c.kind === v ? 'selected' : ''}>${label[v]}</option>`).join('')}</select></td>
      <td class="num">${c.table.length - 1}</td>
      <td><small>${esc((c.table[0] || []).slice(0, 6).join('、'))}${(c.table[0] || []).length > 6 ? ' …' : ''}</small></td>
      <td>${esc(c.result || '')}</td></tr>`).join('')}
    </tbody></table>`;
}

/* ---------- 標準図 ---------- */
let std = { files: [], list: [] };

async function loadStdList() {
  const box = $('#stdList');
  if (!officePin || !box) return;
  try {
    std.list = await run('stdList', officePin);
    const notSaved = std.list.filter(x => x.hasPdf && !x.saved).length;
    box.innerHTML = std.list.length ? `
      ${notSaved ? `<p class="st-warn">標準図フォルダの外にある図面が ${notSaved} 件あります。元のファイルが消えると表示できなくなるので、フォルダにまとめて保存してください。
        <button class="btn sm" data-stdcollect>標準図フォルダにまとめて保存</button></p>` : '<p class="st-ok">すべての標準図が標準図フォルダに保存されています</p>'}
      <table class="tbl"><thead><tr><th>図番</th><th>図面名</th><th>適用条件（自動で選ぶ条件）</th><th>見るところ</th><th>保存場所</th></tr></thead><tbody>
      ${std.list.map(x => `<tr><td class="mono"><b>${esc(x.no)}</b></td><td>${esc(x.name)}</td>
        <td>${x.cond ? `<small>${esc(x.cond)}</small>` : '<span class="st-ng">未設定（自動では選ばれません）</span>'}</td>
        <td>${x.points ? `${x.points}か所${x.noPos ? `<br><small class="st-warn">位置未登録 ${x.noPos}</small>` : ''}` : '<span class="note">なし</span>'}</td>
        <td>${!x.hasPdf ? '<span class="st-ng">図面なし</span>' : x.saved ? '<span class="st-ok">標準図フォルダ</span>' : '<span class="st-warn">別の場所</span>'}</td></tr>`).join('')}
      </tbody></table>` : '<p class="note">まだ標準図は登録されていません。</p>';
  } catch (e) {
    box.innerHTML = `<p class="st-ng">読み込めませんでした：${esc(e.message)}</p>`;
  }
}

function pickStdFiles(e) {
  const files = [...e.target.files];
  e.target.value = '';
  if (!files.length) return;
  std.files = files.map(f => ({ file: f, no: f.name.replace(/\.pdf$/i, '').normalize('NFKC').replace(/\s*\(\d+\)$/, '').trim(), result: '' }));
  renderStdNew();
}

function renderStdNew() {
  const box = $('#stdNew');
  if (!std.files.length) { box.innerHTML = ''; return; }
  const has = no => std.list.find(x => String(x.no).toUpperCase() === String(no).toUpperCase());
  box.innerHTML = `<h4 style="margin:12px 0 6px">保存する標準図（${std.files.length}件）</h4>
    <table class="tbl"><thead><tr><th>ファイル</th><th>図番</th><th>図面名（空欄なら今のまま）</th><th>適用条件（空欄なら今のまま）</th><th></th></tr></thead><tbody>
    ${std.files.map((f, k) => { const h = has(f.no); return `<tr>
      <td><small>${esc(f.file.name)}</small></td>
      <td><input data-stdno="${k}" value="${esc(f.no)}" style="width:150px;padding:8px;border:1px solid var(--rule);border-radius:6px"></td>
      <td><input data-stdname="${k}" value="" placeholder="${esc(h ? h.name : '例：小便器ユニット 3連')}" style="width:100%;padding:8px;border:1px solid var(--rule);border-radius:6px"></td>
      <td><input data-stdcond="${k}" value="" placeholder="${esc(h ? h.cond : '例：ユニット種類=U; 連数=3')}" style="width:100%;padding:8px;border:1px solid var(--rule);border-radius:6px"></td>
      <td>${f.result ? esc(f.result) : h ? '<span class="st-warn">差し替え</span>' : '<span class="st-ok">新規</span>'}</td></tr>`; }).join('')}
    </tbody></table>
    <button class="btn primary big" data-stdsave style="margin-top:10px">標準図フォルダに保存する</button>`;
}

async function saveStdFiles() {
  const staff = needStaff();
  if (!staff) return;
  std.files.forEach((f, k) => {
    f.no = $(`[data-stdno="${k}"]`).value.trim();
    f.name = $(`[data-stdname="${k}"]`).value.trim();
    f.cond = $(`[data-stdcond="${k}"]`).value.trim();
  });
  if (std.files.some(f => !f.no)) return alert('図番が空の行があります');
  const repl = std.files.filter(f => std.list.some(x => String(x.no).toUpperCase() === f.no.toUpperCase())).length;
  if (!confirm(`標準図 ${std.files.length} 件を保存します${repl ? `（うち差し替え ${repl} 件。古い図面もフォルダに残ります）` : ''}。よろしいですか？`)) return;
  for (const f of std.files) {
    if (String(f.result).indexOf('✔') === 0) continue;
    try {
      f.result = '保存中…'; renderStdNew();
      const r = await run('saveStandardDrawing', officePin, f.no, f.name, f.cond, await readAsBase64(f.file), staff);
      f.result = '✔ ' + (r.isNew ? '新規で保存' : '差し替え');
    } catch (err) {
      f.result = '失敗：' + err.message;
    }
    renderStdNew();
  }
  toast('標準図を保存しました');
  loadStdList();
}

async function collectStd() {
  if (!confirm('標準図フォルダの外にある標準図を、フォルダにコピーして保存します。よろしいですか？')) return;
  loading(true);
  try {
    const r = await run('collectStandardDrawings', officePin);
    toast(`${r.copied}件を標準図フォルダに保存しました`);
    if (r.failed.length) alert('保存できなかった図面：' + r.failed.join('、') + '（元のファイルが見つかりません）');
  } catch (e) {
    alert('保存できませんでした：' + e.message);
  } finally { loading(false); }
  loadStdList();
}

// QRの中身から指図NO・組立品番・工事名を取り出す（指示書のQRでなければ null）
function qrInfo(text) {
  const s = String(text || '').replace(/　/g, ' ').trim();
  const t = s.split(/ {2,}/);
  if (!/^\d{10,}$/.test(t[0] || '')) return null;
  const di = t.findIndex(x => /\d{4}\/\d{2}\/\d{2}/.test(x));
  return { id: t[0], hin: di >= 0 ? (t[di + 3] || '') : '', koji: di >= 0 ? String(t[di + 2] || '').normalize('NFKC') : '' };
}

async function analyzeOfficeFiles(e) {
  const files = [...e.target.files];
  e.target.value = '';
  if (!files.length) return;
  if (!needStaff()) return;
  office = { files: [], pages: [], results: {}, parts: {}, csv: [] };
  // CSVは先に読む（PDFとは別に、種類を見分けて取り込む）
  for (const f of files.filter(isCsvFile)) {
    try {
      const table = parseCsv(await readCsvText(f));
      office.csv.push({ name: f.name, table, kind: csvKind(table), result: '' });
    } catch (err) {
      office.csv.push({ name: f.name, table: [[]], kind: '', result: '読めませんでした：' + err.message });
    }
  }
  files.splice(0, files.length, ...files.filter(f => !isCsvFile(f)));
  renderOffice();
  if (!files.length) { offProg(`CSVを読みました（${office.csv.length}ファイル）。種類を確認して「登録する」を押してください。`); return; }
  const warn = ev => { ev.preventDefault(); ev.returnValue = ''; };
  window.addEventListener('beforeunload', warn);
  try {
    for (const f of files) {
      const fi = office.files.length;
      const isPdf = /pdf/i.test(f.type) || /\.pdf$/i.test(f.name);
      const rec = { name: f.name, isPdf, bytes: null, jpg: null };
      office.files.push(rec);
      if (isPdf) {
        rec.bytes = new Uint8Array(await f.arrayBuffer());
        const doc = await pdfjsLib.getDocument({ data: rec.bytes.slice(0) }).promise;   // 元のデータは分割用に残す
        for (let p = 1; p <= doc.numPages; p++) {
          offProg(`読み取り中：${f.name}　${p} / ${doc.numPages} ページ`);
          const page = await doc.getPage(p);
          const v1 = page.getViewport({ scale: 1 });
          const big = Math.max(v1.width, v1.height);
          const { cv, text } = await readPdfPage(page);
          await addOfficePage(fi, p - 1, cv, big > 1000, text);   // A4の長辺は約842pt、A3は約1191pt
        }
      } else {
        // 写真：JPEGに直して1ページとして扱う
        const img = await loadImage(f);
        const sc = Math.min(1, 3500 / Math.max(img.naturalWidth, img.naturalHeight));
        const cv = document.createElement('canvas');
        cv.width = Math.round(img.naturalWidth * sc); cv.height = Math.round(img.naturalHeight * sc);
        cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
        rec.jpg = base64ToBytes(cv.toDataURL('image/jpeg', 0.85).split(',')[1]);
        rec.w = cv.width; rec.h = cv.height;
        offProg(`読み取り中：${f.name}`);
        await addOfficePage(fi, 0, cv, true, null);
      }
    }
    const n = new Set(office.pages.filter(p => p.info).map(p => p.info.id)).size;
    offProg(`読み取り完了：${office.pages.length}ページ・指示書${n}件。仕分けを確認して「登録する」を押してください。`);
  } catch (err) {
    offProg('読み取りに失敗しました：' + err.message);
  }
  window.removeEventListener('beforeunload', warn);
  renderOffice();
}

/**
 * スキャンPDFの1ページからQRを読む
 * 白黒スキャンは、スキャンした解像度（200・300・400dpi）ちょうどで描くと読みやすい。
 * 中途半端に拡大すると細かい点がつぶれて読めないことがあるので、まずその解像度で試す
 */
async function readPdfPage(page) {
  let last = null;
  for (const dpi of [200, 300, 400, 250]) {
    const vp = page.getViewport({ scale: dpi / 72 });
    const cv = document.createElement('canvas');
    cv.width = Math.round(vp.width); cv.height = Math.round(vp.height);
    await page.render({ canvasContext: cv.getContext('2d'), viewport: vp }).promise;
    if (window.ZXingWASM) {
      try {
        const r = await ZXingWASM.readBarcodes(cv.getContext('2d').getImageData(0, 0, cv.width, cv.height),
          { tryHarder: true, tryInvert: true, formats: ['QRCode'], maxNumberOfSymbols: 2 });
        const hit = r.find(x => x.isValid && qrInfo(x.text));
        if (hit) return { cv, text: hit.text };
      } catch (e) {}
    }
    if (last) last.width = last.height = 0;
    last = cv;
  }
  const r = await decodeSource(last);   // 最後に、切り出し・縮小なども試す
  return { cv: last, text: r.text && qrInfo(r.text) ? r.text : '' };
}

async function addOfficePage(fi, p, cv, big, text) {
  if (text === null || text === undefined) text = (await decodeSource(cv)).text || '';
  const r = { text };
  const info = r.text ? qrInfo(r.text) : null;
  let isParam = false;
  if (!info && big) { try { isParam = isParamSheet(cv); } catch (e) { /* 見分けられなければ特図のまま */ } }
  const t = document.createElement('canvas');
  const sc = 240 / Math.max(cv.width, cv.height);
  t.width = Math.round(cv.width * sc); t.height = Math.round(cv.height * sc);
  t.getContext('2d').drawImage(cv, 0, 0, t.width, t.height);
  office.pages.push({
    fi, p, qr: info ? r.text : '', info, big, thumb: t.toDataURL('image/jpeg', 0.7),
    type: info ? '指示書' : isParam ? 'パラメータ表' : (big ? '特図' : '指示書'),
  });
  cv.width = cv.height = 0;
  renderOffice();
}

// ページを指示書ごとにまとめる
//  ・QRのある指示書ページ → その指図NOの指示書
//  ・QRが読めなかった指示書ページ → 同じA4の並び（指示書の続き）の中のQRで判断（推定＝要確認）
//  ・特図・パラメータ表 → 直前の指示書
//  ・ページごとに「所属」を選べば、それを優先
function groupOffice() {
  const groups = [], owner = {}, guess = {};
  const grp = (id, k) => {
    let g = groups.find(x => x.id === id);
    if (!g) {
      const src = office.pages.find(p => p.info && p.info.id === id) || office.pages[k];
      g = { id, qr: src.qr, hin: src.info ? src.info.hin : '', koji: src.info ? src.info.koji : '', shiji: [], tokuzu: [], param: [] };
      groups.push(g);
    }
    return g;
  };
  const put = (k, id) => {
    owner[k] = id;
    if (!id) return;
    const pg = office.pages[k], g = grp(id, k);
    ({ '指示書': g.shiji, '特図': g.tokuzu, 'パラメータ表': g.param })[pg.type].push(k);
  };
  let cur = null, prev = null, pending = [];
  office.pages.forEach((pg, k) => {
    if (pg.type === '使わない') return;
    if (pg.forceId) {
      put(k, pg.forceId);
      if (pg.type === '指示書') cur = pg.forceId;
      prev = pg.type;
      return;
    }
    if (pg.type === '指示書') {
      if (pg.info) {
        cur = pg.info.id;
        pending.forEach(j => { put(j, cur); guess[j] = true; });   // 並びの先頭でQRが読めなかったページ
        pending = [];
        put(k, cur);
      } else if (prev === '指示書' && cur) {
        put(k, cur); guess[k] = true;                               // 指示書の続き
      } else {
        pending.push(k);                                            // 並びの先頭：後ろのQRを待つ
      }
    } else {
      pending.forEach(j => { owner[j] = null; });
      pending = [];
      put(k, cur);
    }
    prev = pg.type;
  });
  pending.forEach(j => { owner[j] = null; });
  groups.forEach(g => ['shiji', 'tokuzu', 'param'].forEach(t => g[t].sort((a, b) => a - b)));
  const qrs = groups.filter(g => g.qr && qrInfo(g.qr));
  return { groups: qrs, owner, guess };
}

function renderOffice() {
  const { groups, owner, guess } = groupOffice();
  const ids = [...new Set(office.pages.filter(p => p.info).map(p => p.info.id))];
  const short = id => String(id || '').replace(/^0+(?=\d)/, '');
  const orphans = Object.keys(owner).filter(k => owner[k] === null).length;
  $('#offCsv').innerHTML = csvHtml();
  $('#offGroups').innerHTML = !groups.length && office.csv && office.csv.length
    ? '<button class="btn primary big" data-offreg style="margin-top:10px">登録する</button>'
    : groups.length ? `
    <h4 style="margin:12px 0 6px">登録する内容（${groups.length}件）</h4>
    <table class="tbl"><thead><tr><th>指図NO</th><th>組立品番</th><th>工事名</th><th>指示書</th><th>特図</th><th>パラメータ表</th><th>結果</th></tr></thead><tbody>
    ${groups.map(g => `<tr><td class="mono">${esc(short(g.id))}</td><td class="mono">${esc(g.hin)}</td><td>${esc(g.koji)}</td>
      <td>${g.shiji.length}p</td><td>${g.tokuzu.length ? `<b>${g.tokuzu.length}p</b>` : '<span class="note">なし（標準品）</span>'}</td><td>${g.param.length ? `${g.param.length}p ${(office.paramRead || {})[g.id] ? '<span class="st-ok">✔ 数値登録済</span>' : `<button class="btn sm" data-offpread="${esc(g.id)}">数値を読み取る</button>`}` : '-'}</td>
      <td>${esc(office.results[g.id] || '')}</td></tr>`).join('')}
    </tbody></table>
    ${orphans ? `<p class="st-ng">⚠ どの指示書にも属さないページが ${orphans} ページあります（最初のページより前にQRがありません）。「使わない」にするか、並びを確認してください。</p>` : ''}
    <button class="btn primary big" data-offreg style="margin-top:10px">登録する</button>` : '';
  $('#offPages').innerHTML = office.pages.length ? `<h4 style="margin:14px 0 6px">ページの仕分け（違っていたら直してください）</h4>
    <div class="offpages">${office.pages.map((pg, k) => `
      <div class="offpg ${pg.info ? 'qr' : ''}" ${guess[k] && !pg.forceId ? 'style="border:2px solid #d4a72c"' : ''}>
        <img src="${pg.thumb}" alt="">
        <div>${esc(office.files[pg.fi].name)}　${pg.p + 1}ページ（${pg.big ? 'A3以上' : 'A4'}）</div>
        <div>${pg.info ? `QR：指図NO ${esc(short(pg.info.id))}` : 'QRなし'}</div>
        <select data-pgtype="${k}">${['指示書', '特図', 'パラメータ表', '使わない'].map(t => `<option ${t === pg.type ? 'selected' : ''}>${t}</option>`).join('')}</select>
        <select data-pgowner="${k}"><option value="">所属：自動</option>${ids.map(id => `<option value="${esc(id)}" ${pg.forceId === id ? 'selected' : ''}>所属：${esc(short(id))}</option>`).join('')}</select>
        <div class="grp">${owner[k] ? `→ ${esc(short(owner[k]))}${guess[k] && !pg.forceId ? ' <span class="st-warn">（推定・要確認）</span>' : ''}` : owner[k] === null ? '<span class="st-ng">→ 指示書なし</span>' : ''}</div>
      </div>`).join('')}</div>` : '';
}

// 指定したページだけのPDFを作る（base64）
async function buildOfficePdf(idxs) {
  const out = await PDFLib.PDFDocument.create();
  for (const k of idxs) {
    const pg = office.pages[k], f = office.files[pg.fi];
    if (f.isPdf) {
      // 元のPDFは1回だけ読み込んで使い回す（大きなPDFでも遅くならないように）
      f.lib = f.lib || await PDFLib.PDFDocument.load(f.bytes.slice(0), { ignoreEncryption: true });
      const [cp] = await out.copyPages(f.lib, [pg.p]);
      out.addPage(cp);
    } else {
      const img = await out.embedJpg(f.jpg);
      const page = out.addPage([img.width, img.height]);
      page.drawImage(img, { x: 0, y: 0, width: img.width, height: img.height });
    }
  }
  return out.saveAsBase64();
}

async function registerOffice() {
  const staff = needStaff();
  if (!staff) return;
  const { groups, owner } = groupOffice();
  const csvs = (office.csv || []).filter(c => c.kind && String(c.result).indexOf('✔') !== 0);
  if (csvs.length) {
    // CSVを先に取り込む（指示書の一覧 → パラメータの順）
    const kn = { order: '指示書の一覧', param: 'パラメータ', parts: '部品リスト' };
    if (!confirm(`CSV ${csvs.length} ファイルを取り込みます（${csvs.map(c => c.name + '：' + kn[c.kind]).join('、')}）。よろしいですか？`)) return;
    for (const c of csvs.sort((a, b) => (a.kind === 'order' ? 0 : 1) - (b.kind === 'order' ? 0 : 1))) {
      try {
        if (c.kind === 'order') {
          const rows = csvOrderRows(c.table);
          if (!rows.length) throw new Error('「指図NO」の列が見つかりません');
          const r = await run('registerOrderRows', officePin, rows, staff);
          c.result = `✔ 新規 ${r.added}件・更新 ${r.updated}件${r.skipped ? `・指図NOなし ${r.skipped}行` : ''}`;
        } else if (c.kind === 'parts') {
          const rows = csvPartRows(c.table);
          if (!rows.length) throw new Error('「指図NO」と「品番」のある行がありません');
          const r = await run('importPartRows', officePin, rows, staff);
          c.result = `✔ 指示書 ${r.orders}件・部品 ${r.parts}行`;
        } else {
          c.result = '✔ ' + await run('importParamRows', officePin, c.table, staff);
        }
      } catch (err) {
        c.result = '失敗：' + err.message;
      }
      renderOffice();
    }
    loadOfficeStatus();
    if (!groups.length) { toast('CSVを取り込みました'); return; }
  }
  if (!groups.length) return alert('指示書（QR）が見つかりません');
  if (!window.PDFLib) return alert('PDFを分ける部品を読み込めませんでした。ページを再読み込みしてください');
  const orphans = Object.keys(owner).filter(k => owner[k] === null).length;
  if (orphans && !confirm(`どの指示書にも属さないページが ${orphans} ページあります。それらは登録しません。続けますか？`)) return;
  const tk = groups.filter(g => g.tokuzu.length).length;
  if (!confirm(`指示書 ${groups.length} 件を登録します（うち特図あり ${tk} 件）。よろしいですか？`)) return;
  const keep = $('#offKeep').checked;
  const warn = e => { e.preventDefault(); e.returnValue = ''; };
  window.addEventListener('beforeunload', warn);   // 登録中に画面を閉じようとしたら確認を出す
  try {
    offProg('指示書を登録中…');
    const todo = groups.filter(g => String(office.results[g.id] || '').indexOf('✔') !== 0);
    const res = await run('registerOrders', officePin, todo.map(g => g.qr), staff);
    res.forEach(r => { if (r.ok) office.results[r.id] = r.existed ? '登録済み（前から）' : '登録'; });
    for (let n = 0; n < groups.length; n++) {
      const g = groups[n];
      if (String(office.results[g.id] || '').indexOf('✔') === 0) continue;   // もう終わった指示書は飛ばす（続きから）
      offProg(`アップロード中：${n + 1} / ${groups.length} 件（${g.hin || g.id}）`);
      // 原本・特図・パラメータ表それぞれ、終わったものは記録して、やり直しのときに飛ばす
      const part = office.parts[g.id] = office.parts[g.id] || {};
      const done = [];
      if (keep && g.shiji.length) {
        if (!part.shiji) { await run('saveOrderDoc', officePin, g.id, 'shiji', await buildOfficePdf(g.shiji), staff); part.shiji = true; }
        done.push('原本');
      }
      if (g.tokuzu.length) {
        if (!part.tokuzu) { await run('officeSaveTokuzu', officePin, g.id, '一括スキャン', await buildOfficePdf(g.tokuzu), staff); part.tokuzu = true; }
        done.push('特図');
      }
      if (g.param.length) {
        if (!part.param) { await run('saveOrderDoc', officePin, g.id, 'param', await buildOfficePdf(g.param), staff); part.param = true; }
        done.push('パラメータ表');
      }
      office.results[g.id] = '✔ ' + (office.results[g.id] || '') + (done.length ? '・' + done.join('・') : '');
      // U の特図・原本は、テスリを読み取るための文字認識を裏で先に済ませておく（待たない）
      if (g.tokuzu.length || (keep && g.shiji.length)) run('prepareHandrail', officePin, g.id).catch(() => {});
      renderOffice();
    }
    offProg(`登録が完了しました（${groups.length}件）。下の登録状況で確認できます。`);
    toast('登録しました');
  } catch (err) {
    offProg('途中で失敗しました：' + err.message + '（もう一度「登録する」を押すと、終わっていない分だけ続きから登録します）');
  }
  window.removeEventListener('beforeunload', warn);
  renderOffice();
  loadOfficeStatus();
}

// Excelからコピーした表（タブ区切り）を取り込む
async function importPasted() {
  const staff = needStaff();
  if (!staff) return;
  const text = $('#offParam').value.replace(/\r/g, '').trim();
  if (!text) return alert('Excelからコピーした表を貼り付けてください');
  const lines = text.split('\n').filter(l => l.trim());
  const sep = lines[0].indexOf('\t') >= 0 ? '\t' : ',';
  const table = lines.map(l => l.split(sep).map(c => c.trim().replace(/^"(.*)"$/, '$1')));
  if (table.length < 2) return alert('見出しの行と、データの行を貼り付けてください');
  if (!confirm(`${table.length - 1}行（現場）のパラメータを取り込みます。同じ組立品番・指図NOの古いパラメータは置き換えます。よろしいですか？`)) return;
  loading(true);
  try {
    const msg = await run('importParamRows', officePin, table, staff);
    $('#offParamMsg').textContent = msg;
    $('#offParam').value = '';
    toast('取り込みました');
    loadOfficeStatus();
  } catch (e) {
    alert('取り込めませんでした：' + e.message);
  } finally { loading(false); }
}

let offStat = [], offFilter = '', offQ = '';
const offSel = new Set();   // 削除するために選んだ指示書
async function loadOfficeStatus() {
  const box = $('#offStatus');
  if (!officePin || !box) return;
  try {
    offStat = await run('officeStatus', officePin);
    renderOfficeStatus();
  } catch (e) {
    box.innerHTML = `<p class="st-ng">読み込めませんでした：${esc(e.message)}</p>`;
  }
}

const same = (a, b) => String(a || '').replace(/^0+(?=\d)/, '') === String(b || '').replace(/^0+(?=\d)/, '');
// 間違えて登録した指示書を削除する（消した内容は「削除記録」シートに残る）
async function deleteOrders(ids, after) {
  const staff = needStaff();
  if (!staff || !ids.length) return false;
  const short = id => String(id || '').replace(/^0+(?=\d)/, '');
  const info = id => {
    const o = cur && same(cur.order['指図NO'], id) ? cur.order : null;
    const x = offStat.find(v => same(v.id, id)) || (o ? { hin: o['組立品番'], koji: o['工事名'], floor: o['適用階'] } : {});
    return `・${short(id)}　${x.hin || ''} ${x.koji || ''} ${x.floor || ''}`.trim(); };
  const lines = ids.slice(0, 12).map(info).join('\n') + (ids.length > 12 ? `\n…ほか${ids.length - 12}件` : '');
  if (!confirm(`次の指示書 ${ids.length}件を削除します。\n${lines}\n\n部品・パラメータ（指図NOで登録した分）・図面の確認・書き込みも消え、指示書の原本と、この指示書だけの特図はドライブのゴミ箱に移します。\nよろしいですか？`)) return false;
  loading(true);
  try {
    let r = await run('deleteOrders', officePin, ids, staff, false);
    if (r.needConfirm) {
      loading(false);
      const w = r.needConfirm.map(x => `・${short(x.id)}　${x.state || ''}${x.quality ? '　品質記録' + x.quality + '件' : ''}${x.work ? '　作業実績' + x.work + '件' : ''}`).join('\n');
      if (!confirm(`作業が始まっている、または記録がある指示書が含まれています。\n${w}\n\n品質記録・作業実績は消さずに残します。本当に削除しますか？`)) return false;
      loading(true);
      r = await run('deleteOrders', officePin, ids, staff, true);
    }
    const files = r.results.reduce((n, x) => n + x.files, 0);
    toast(`${r.results.length}件を削除しました${files ? `（ファイル${files}件をゴミ箱へ）` : ''}`);
    ids.forEach(id => offSel.delete(id));
    if (after) after();
    loadOfficeStatus();
    return true;
  } catch (e) {
    alert('削除できませんでした：' + e.message);
    return false;
  } finally { loading(false); }
}
const deleteSelectedOrders = ids => deleteOrders(ids);

// 図面が決まっていない（要対応）指示書を上に、絞り込み・検索つきで表示
function renderOfficeStatus() {
  const box = $('#offStatus');
  const short = id => String(id || '').replace(/^0+(?=\d)/, '');
  const rank = x => ({ none: 0, nomatch: 0, multi: 1 }[x.kind] ?? 2);
  const need = x => rank(x) < 2;
  const list = offStat.slice().sort((a, b) => rank(a) - rank(b) || String(a.ship).localeCompare(String(b.ship)));
  [...offSel].forEach(id => { if (!list.some(x => x.id === id)) offSel.delete(id); });
  const ng = list.filter(need).length;
  if (!offFilter) offFilter = ng ? 'need' : 'all';
  if (!ng && offFilter === 'need') offFilter = 'all';
  const nb = $('#nvOffNg');
  if (nb) { nb.textContent = ng ? '要対応' + ng : ''; nb.className = ng ? 'ng' : ''; }
  const q = offQ.trim().toUpperCase();
  const shown = list.filter(x => (offFilter === 'all' || need(x)) &&
    (!q || [x.id, short(x.id), x.hin, x.koji, x.floor, x.unit].some(v => String(v || '').toUpperCase().includes(q))));
  const dw = x => x.kind === 'tokuzu' ? '<span class="st-ok">特図</span>'
    : x.kind === 'std' ? `<span class="st-ok">標準図 ${esc(x.drawing)}</span>`
    : x.kind === 'fixed' ? `<span class="st-ok">${esc(x.drawing)}</span>`
    : x.kind === 'multi' ? `<span class="st-warn">候補が複数：${esc(x.drawing)}</span>`
    : x.kind === 'nomatch' ? '<span class="st-ng">合う標準図なし</span>'
    : '<span class="st-ng">未登録（特図かパラメータが必要）</span>';
  const cnt = k => list.filter(x => x.kind === k).length;
  box.innerHTML = `<p>${ng ? `<span class="st-ng">⚠ 図面が決まっていない指示書が ${ng} 件あります</span>` : '<span class="st-ok">すべての指示書で図面が決まっています</span>'}
      <span class="note">（行を押すと、現場と同じ画面で確認できます）</span></p>
    <div class="offsum"><span>全 ${list.length}件</span><span>特図 ${cnt('tokuzu')}</span><span>標準図 ${cnt('std')}</span>${ng ? `<span class="ng">要対応 ${ng}</span>` : ''}</div>
    <div class="offbar">
      <div class="seg" data-value="${offFilter}">
        <button data-offfilter="need" class="${offFilter === 'need' ? 'on' : ''}">要対応だけ（${ng}）</button>
        <button data-offfilter="all" class="${offFilter === 'all' ? 'on' : ''}">すべて（${list.length}）</button></div>
      <input id="offQ" value="${esc(offQ)}" placeholder="指図NO・品番・工事名で探す" autocomplete="off" aria-label="登録状況の検索">
      ${offSel.size ? `<button class="btn danger" data-offdel>選んだ ${offSel.size}件を削除</button><button class="btn sm" data-offselclear>選択をやめる</button>` : ''}
    </div>
    ${shown.length ? `<table class="tbl offstat"><thead><tr><th class="sel"><input type="checkbox" data-offselall aria-label="表示中をすべて選ぶ" ${shown.every(x => offSel.has(x.id)) ? 'checked' : ''}></th><th>指図NO</th><th>ユニット</th><th>組立品番</th><th>工事名・階</th><th>出荷日</th><th>原本</th><th>図面</th><th>パラメータ</th><th>状態</th></tr></thead><tbody>
    ${shown.map(x => `<tr data-offopen="${esc(x.id)}" class="${need(x) ? 'need' : ''} ${offSel.has(x.id) ? 'picked' : ''}"><td class="sel"><input type="checkbox" data-offsel="${esc(x.id)}" ${offSel.has(x.id) ? 'checked' : ''} aria-label="選ぶ"></td><td class="mono">${esc(short(x.id))}</td><td>${x.unit ? `<span class="unit">${esc(x.unit)}<small>${esc(UNITS[x.unit] || '')}</small></span>` : '-'}</td><td class="mono">${esc(x.hin)}</td>
      <td>${esc(x.koji)} ${esc(x.floor)}</td><td>${dueChip(x.ship)}${esc(x.ship)}</td><td>${x.shiji ? '<span class="st-ok">✔</span>' : '-'}</td>
      <td>${dw(x)}</td><td>${x.params ? x.params + '項目' : (x.kind === 'tokuzu' ? '<span class="note">不要</span>' : '-')}</td><td>${esc(x.state)}</td></tr>`).join('')}
    </tbody></table>` : '<p class="note">該当する指示書はありません</p>'}`;
}

