  $('#rlBody').innerHTML=`<div class="rl-grid"><div>${rl.edit?`<div class="rl-card"><h3>① 図面と自動選定条件</h3><label>図番<input id="rlNo" value="${rlEsc(no)}" ${no?'readonly':''} placeholder="例：K-UTNUA03A"></label><label>図面名<input id="rlName" value="${rlEsc(d&&d['組図名'])}"></label><label>Google DriveのPDF・画像URL<input id="rlUrl" value="${rlEsc(d&&d['PDFのURL'])}" placeholder="https://drive.google.com/file/d/…/view"></label><p class="rl-muted">PDFをお持ちの場合は、事務画面の「標準図のPDFを選ぶ」から取り込めます。</p><div id="rlDrawConditions"></div><p class="rl-muted">条件なしで保存すると、手動選択専用になります。</p><button class="btn primary" id="rlSaveDrawing">図面・選定条件を保存</button></div><div class="rl-card"><h3>② 条件ごとのマーキング</h3>${no?'<select id="rlPointSelect" aria-label="編集するマーキング"></select><button class="btn sm" id="rlNewPoint">＋ 印を追加</button><div id="rlPointForm"></div>':'<p>先に図面を保存すると印を登録できます。</p>'}</div><div class="rl-card"><h3>③ 登録済みパラメータで確認</h3><label>確認する指図NO<input id="rlPreviewOrder" placeholder="指図NOを入力" value="${rlEsc(cur&&cur.order&&cur.order['指図NO']||'')}"></label><button class="btn" id="rlPreview">適用結果を確認</button><button class="btn sm" id="rlAllMarks">全ルール表示に戻す</button><p class="rl-muted">図面には保存済みの印を表示します。編集した印は保存後に確認してください。</p><div id="rlPreviewResult" class="rl-result"></div></div>`:`<div class="rl-card"><h3>${rlEsc(item.name)}</h3><p>${rlEsc(item.no)}</p><p>${rlEsc(item.cond||'自動選定条件なし')}</p><p class="${item.matches?'rl-match':'rl-muted'}">${item.matches?'現在のパラメータに一致':'現在のパラメータとの一致は確認できません'}</p><button class="btn primary" id="rlUse">この図面を案件に指定</button><p class="rl-muted">指示書の図面指定を保存します。共通ルールやパラメータは変更しません。</p></div>`}</div><div><div class="rl-row"><button class="btn sm" id="rlPrevPage">前ページ</button><span id="rlPageLabel"></span><button class="btn sm" id="rlNextPage">次ページ</button><button class="btn sm" id="rlZoomOut">縮小</button><button class="btn sm" id="rlZoomIn">拡大</button></div><p class="rl-muted" id="rlDrawHelp">印を編集するときは「図面をなぞって位置指定」を押してください。</p><div class="rl-scroll"><div class="rl-stage" id="rlStage"><canvas id="rlCanvas"></canvas><div class="rl-marks" id="rlMarks"></div></div></div></div></div>`;
  if(rl.edit){rlConditions('rlDrawConditions',d&&d['適用条件']);$('#rlSaveDrawing').onclick=()=>rlTask(rlSaveDrawing);if(no){rlPointOptions();$('#rlPointSelect').onchange=async()=>{if(await rlCanChangePoint())rlPointEdit($('#rlPointSelect').value);else $('#rlPointSelect').value=rl.point.row['ポイントNO']||'';};$('#rlNewPoint').onclick=async()=>{if(await rlCanChangePoint())rlPointEdit('');};}$('#rlPreview').onclick=()=>rlTask(rlPreview);$('#rlAllMarks').onclick=()=>{rl.preview=null;rlMarks();};}else $('#rlUse').onclick=()=>rlTask(()=>rlChoose(item));
  $('#rlPrevPage').onclick=()=>rlTask(()=>rlPage(-1));$('#rlNextPage').onclick=()=>rlTask(()=>rlPage(1));$('#rlZoomIn').onclick=()=>{rl.zoom=Math.min(4,rl.zoom+.5);$('#rlStage').style.width=rl.zoom*100+'%';};$('#rlZoomOut').onclick=()=>{rl.zoom=Math.max(1,rl.zoom-.5);$('#rlStage').style.width=rl.zoom*100+'%';};
  const url=rl.edit?d&&d['PDFのURL']:item.url;
  if(url){const seq=rl.seq;const f=await run('getDrawingFile',url);if(seq!==rl.seq)return;const bytes=base64ToBytes(f.data);if(/pdf/i.test(f.mime)){rl.pdf=await pdfjsLib.getDocument({data:bytes}).promise;}else if(/^image\//.test(f.mime)){rl.img=await loadImage(new Blob([bytes],{type:f.mime}));}else throw new Error('PDFまたは画像を指定してください');await rlRenderPage();}
