async function rlSaveDrawing(){const no=$('#rlNo').value.trim(),data={no,name:$('#rlName').value,url:$('#rlUrl').value.trim(),cond:rlCondValue('rlDrawConditions')};if(!getMe())throw new Error('画面上部に担当者名を入力してから保存してください');if(!await rlAsk('この図面の共通選定条件を保存します。今後の自動選定にも適用されます。保存しますか？'))return;await run('saveDrawingRule',officePin,data,rl.data.version,getMe());rl.drawDirty=false;rl.dirty=!!rl.pointDirty;rl.list=await run('drawingLibrary',cur&&cur.order&&cur.order['指図NO']||'');if(!rl.no){rl.dirty=false;await rlOpen(no);}else{const fresh=await run('getDrawingRule',officePin,no);rl.data.drawing=fresh.drawing;rl.data.version=fresh.version;}rlStatus('図面と選定条件を保存しました'+(rl.pointDirty?'。編集中の印はまだ未保存です':''));loadStdList();}
function rlPointOptions(selected){const sel=$('#rlPointSelect');sel.innerHTML='<option value="">新しい印</option>'+rl.data.points.map(({row:p})=>`<option value="${rlEsc(p['ポイントNO'])}">${rlEsc(p['ポイントNO'])}：${rlEsc(p['確認内容'])}${p['有効']==='無効'?'（無効）':''}</option>`).join('');sel.value=selected||'';rlPointEdit(selected||'');}
